    bag_examples_v2_toast: "🎁 Mifano mipya kwenye mkoba wako: mawazo ya zawadi, orodha ya hoteli na orodha ya safari ya ndege ✨",
    faq_a_bag_examples_list: "Mkoba mpya huja na mifano unayoweza kubadilisha au kufuta kama kitu kingine chochote: Nyumbani (manunuzi, mapishi, milo ya wiki hii), Familia (nyakati ndogo, orodha ya sherehe ya kuzaliwa, shughuli na madarasa), Mawazo (mawazo ya wikendi, mawazo ya zawadi kulingana na ukaribu wako na mtu huyo, na nini cha kufanya na pesa ulizoweka akiba) na Safari (mahali unapotaka kwenda, vitu vya safari, vitu vya hotelini na orodha ya safari ya ndege nje ya nchi). Mkoba uliokuwepo tayari hupata mifano mipya zaidi mara moja, ndani ya mifuko yake yenyewe.",
    faq_q_bag_examples_list: "Mkoba Wangu una mifano gani?",
    faq_a_nm_me1_guide: "Sky – mhusika wako ndani ya New Me, katika umbo lake la kwanza (Sky 1). Mara ya kwanza, mara tu baada ya kujiunga, lango la mwanga hufunguka likiwa na cheche zinazometa pande zote na Sky huruka kutoka humo, hueleza kwa miguso michache kinachokungoja, kisha hubaki kando ya kila swali: milo inapochaguliwa huandika pamoja nawe katika kitabu chake, na kugusa ushauri wake huonyesha mwingine. Mwishoni Sky husherehekea pamoja nawe na kukupeleka kwenye ziara fupi – na ziara ikiisha, bado ana muda mmoja mdogo zaidi pamoja nawe. Ukiondoka katikati – ya maswali au ya ziara – mara inayofuata Sky hufurahi kukuona na huuliza kama uendelee kutoka pale pale.",
    faq_q_nm_me1_guide: "Nani anaongoza njia ya kuingia New Me?",
