    nm_m1_q_about: "Nimefurahi kukufahamu!",
    nm_m1_q_agree: "Kabla hatujaanza – maneno machache muhimu",
    nm_m1_q_letter: "Maneno kwa nafsi yako ya baadaye? Nitayatunza salama kwa ajili yako",
    nm_m1_q_menu: "Tuandike ndoto pamoja – na tuzitimize pamoja",
    nm_m1_q_plan: "Unaweza kubadilisha wakati wowote – hapa hakuna chaguo baya.",
    nm_m1_q_times: "Nyakati zako ni nyakati zangu pia",
    nm_m1_ready_text: "Kwanza maswali machache madogo – kisha tutachagua milo pamoja.",
    nm_m1_skip: "Ruka",
    nm_m1_tip_ai: "Chakula ambacho hakipo kwenye orodha? Baadaye, kwenye \"Badilisha\", unaweza kukiandika kwa maneno yako mwenyewe – na AI itakihesabu. Na sasa, tuchague pamoja utakachokula kila siku.",
    nm_m1_tip_love: "Na kama hupendi kitu – unaweza kukibadilisha kwa AI wakati wowote. Haijalishi ni chakula gani – ukikipenda, kinabaki kwenye menyu.",
    nm_m1_tip_rice: "Ninaupenda wali kuliko vyote – utakuwa msingi wangu, kwa hivyo nitauchagua. Ninapendekeza uchague kinachojulikana na kitamu.",
    faq_a_shop_basics: "Orodha ya Ununuzi ikiwa tupu kabisa – kwa mfano mwanzoni kabisa – orodha ya msingi ya kuanzia inaonekana: maziwa, mkate, mayai na zaidi. Kugusa kitu kunakiongeza kwenye orodha, na “Ongeza vyote” huongeza kila kitu mara moja. Mara tu kitu kinapokuwa kwenye orodha, orodha ya msingi inatoweka.",
    faq_q_shop_basics: "Orodha ya msingi kwenye Orodha ya Ununuzi tupu ni nini?",
    shop_basics_all: "Ongeza vyote",
    shop_basics_items: "maziwa|mkate|mayai|nyanya|matango|jibini|mchele|tambi|mafuta ya zeituni|matufaha|ndizi|karatasi ya chooni",
    shop_basics_title: "Orodha ya msingi ya kuanzia",
    shop_order_empty: "Orodha iko tupu kwa sasa",
    shop_order_hours: "Saa ngapi?",
    shop_win_evening: "Jioni",
    shop_win_from: "Kuanzia",
    shop_win_morning: "Asubuhi",
    shop_win_noon: "Mchana",
    shop_win_other: "Nyingine…",
    shop_win_to: "Hadi",
    room_genie_again_no: "Si sasa hivi",
    room_genie_again_no_msg: "Basi ni wakati wa kufikia malengo uliyokwisha kujiwekea. Utakapofika kwenye lengo linalofuata – kuna kitu kitakachokungoja huko ✨",
    room_genie_again_q: "Umerudi tena? ✨ Ungependa kubadilisha kitu kingine maishani mwako?",
    room_genie_again_yes: "Ndiyo",
    room_genie_bye: "Tuonane",
    room_genie_rest: "Roho ya msitu inapumzika sasa – rudi kesho ✨",
    faq_a_shop_holidays: "Kwenye Orodha ya Ununuzi, gusa zawadi: sikukuu za nchi yako (iliyochaguliwa katika Mipangilio) zinaonekana kwa mpangilio, pamoja na tarehe zake – zinazohesabiwa zenyewe kila mwaka. Gusa sikukuu ili kupata orodha iliyo tayari ya vitu ambavyo watu hununua kwa ajili yake; vyote vimechaguliwa (isipokuwa vile vilivyo tayari kwenye orodha yako), ondoa alama kwenye usivyohitaji kisha gusa “Ongeza kwenye orodha”. Wiki mbili kabla ya sikukuu, kadi ndogo inaonekana juu ya orodha; ✕ inaificha hadi sikukuu inayofuata.",
    faq_q_shop_holidays: "“Nini cha kununua kwa sikukuu” inafanyaje kazi?",
    shop_hol_add: "Ongeza kwenye orodha ({n})",
    shop_hol_added: "Vimeongezwa kwenye orodha: {n}",
    shop_hol_btn: "Nini cha kununua kwa sikukuu",
    shop_hol_items_title: "{holiday} – nini cha kununua?",
    shop_hol_not_now: "Si sasa",
    faq_a_shop_delivery: "Kwenye Orodha ya Ununuzi, gusa lori: chagua kilichomo kwenye mzigo (vyote vimechaguliwa), lini unafika – leo, kesho au siku nyingine – na saa ngapi (asubuhi, mchana, jioni, au “Nyingine…” kwa saa zako mwenyewe). Vitu hivyo vinahamia kwenye kadi ya “Njiani” juu ya orodha, pamoja na siku na saa. Siku hiyo ikifika, “Mzigo umefika?” unaonekana katika Siku Yangu (na kadi ina “Umefika?”). Kama kila kitu kimefika, vinahamia kwenye “Nunua tena”. Kama kuna kitu kinakosekana, gusa kisichofika nacho kinarudi moja kwa moja kwenye orodha.",
    faq_a_shop_departments: "Orodha inajipanga yenyewe kwa sehemu za supamaketi – matunda na mboga, mikate, maziwa na mayai, nyama na samaki, vyakula vikavu, vilivyogandishwa, vinywaji, vitafunio, usafi, huduma binafsi, watoto wachanga na wanyama vipenzi – ili upite kwenye njia za rafu kwa mpangilio. Sehemu inatambuliwa kutokana na jina la kitu. Kama kitu kimeingia mahali pasipo sahihi, kiguse na uchague sehemu yake, au “Nyingine…” ili uandike yako mwenyewe.",
    faq_a_shop_share_qty: "Ndiyo. Kando ya kila kitu, + inaongeza kimoja zaidi (×2, ×3…) na − inapunguza kimoja. Kitufe cha kushiriki juu ya Orodha ya Ununuzi kinatuma orodha nzima, ikiwa imepangwa vizuri kwa sehemu, kupitia WhatsApp, barua pepe au kama nakala.",
    faq_a_shop_two_buttons: "Zote mbili zinamaanisha “imenunuliwa”. ✕ ni kwa kitu unachonunua mara moja – kinatoka kwenye orodha (na kinasubiri katika 🗑️ kumbukumbu iwapo ilikuwa kosa). ↺ ni kwa vitu unavyonunua tena na tena – vinatoka kwenye orodha na vinasubiri katika “Nunua tena”: kitufe kidogo cha ↺ kando ya pipa la taka chini ya orodha hufungua sehemu hiyo, na mguso mmoja hapo unarudisha kitu kwenye orodha. Kupitia “Hariri” ndani yake unaweza kuondoa kitu kutoka humo. Unapoongeza kitu, vitu ulivyowahi kununua vinaonekana kama mapendekezo, na kama tayari kiko kwenye orodha, kinakuwa ×2 tu badala ya mstari wa pili.",
    faq_q_shop_delivery: "“Nimeagiza mzigo uletwe” hufanyaje kazi?",
    faq_q_shop_departments: "Kwa nini orodha yangu ya ununuzi imegawanywa kwa sehemu?",
