    nm_demo_saved_2: "Mtindi na granola na matunda",
    nm_demo_title: "Hivi ndivyo mlo unavyobadilishwa",
    faq_a_new_me_challenge_journal: "Changamoto inapoisha – kubwa, ndogo au changamoto ya wiki – kwenye sherehe kuna kitufe 📝 Ilikwendaje? kinachofungua ukurasa katika shajara ya changamoto: ilivyohisi (nyuso tano), nini kilisaidia, nini kilikuwa kigumu na nitachukua nini kutoka hapa – hakuna kinacholazimishwa, na kinaweza pia kusubiri baadaye. Shajara ni almasi ndani ya mkoba wa maajabu: kila changamoto iliyoisha pamoja na tarehe yake na kilichoandikwa, mpya zaidi kwanza – gusa mojawapo ili kuisoma, kuihariri au kuishiriki (kinachoshirikiwa ni kilichopo kwenye ukurasa tu). Changamoto iliyoisha pia hupata medali katika mafanikio, chini ya “Changamoto nilizomaliza”. Shajara ya changamoto ni tofauti na shajara ya kawaida.",
    faq_q_new_me_challenge_journal: "Shajara ya changamoto ni nini?",
    nm_badges_challenges: "Changamoto nilizomaliza",
    nm_chj_empty: "Changamoto unazomaliza zitaonekana hapa",
