    nm_chj_mood_4: "Nzuri",
    nm_chj_mood_5: "Nzuri sana",
    nm_chj_q: "Changamoto ilikwendaje?",
    nm_chj_reflect_btn: "Ilikwendaje?",
    nm_chj_save: "Hifadhi kwenye shajara ya changamoto",
    nm_chj_saved: "Imehifadhiwa kwenye shajara ya changamoto",
    nm_chj_share_text: "Nimemaliza changamoto kwenye New Me ✨",
    nm_chj_take: "Nitachukua nini kutoka hapa?",
    nm_chj_title: "Shajara ya changamoto",
    nm_chj_write: "Andika ilivyokwenda",
    nm_swap_time: "Saa",
    faq_a_ai_reminder_in_text: "Ndiyo – kiandike pamoja na kazi, kwa mfano “kesho saa 17:00 kuchukua kifurushi, na kikumbusho saa moja kabla”. Kikumbusho huhifadhiwa kwenye kazi yenyewe: saa moja kabla, nusu saa, siku moja kabla na kadhalika, na “nikumbushe” bila muda maana yake ni dakika 10 kabla. Kikumbusho kilichoandikwa kwenye maandishi kinapewa kipaumbele kuliko sehemu ya kikumbusho iliyo kwenye dirisha hilohilo.",
    faq_q_ai_reminder_in_text: "Je, ninaweza kumwomba msaidizi wa AI kikumbusho katika ombi lilelile?",
    myday_meals_all_done: "Milo yote ya leo imewekewa alama 🍽️",
    nm_tour_week_text: "Changamoto ndogo ya wiki. ✓ kila siku – na ufunguo mwishoni.",
    books_home_chip: "{title} · uk. {page}",
    books_home_of: "kati ya {total}",
    books_home_off_toast: "Kitabu kimeondolewa kwenye skrini ya mwanzo",
    books_home_on_toast: "Kitabu kiko kwenye skrini ya mwanzo 📖",
    books_home_pin: "Kwenye skrini ya mwanzo",
    books_home_q: "Niko ukurasa gani?",
    books_home_save: "Hifadhi",
    faq_a_books_home_chip: "Ndiyo. Kwenye Kona ya Kusoma, kwenye kadi ya kitabu unachosoma, gusa 📌 Kwenye skrini ya mwanzo. Kitufe kidogo chenye kitabu na ukurasa kinaonekana chini ya salamu kwenye skrini ya mwanzo – kigusa, andika namba ya ukurasa mpya na uhifadhi, na maendeleo yanarekodiwa (pia kwenye Kona ya Kusoma). Kugusa 📌 tena kunakiondoa. Vitabu kadhaa vinaweza kuwepo pamoja – kitufe kwa kila kimoja – na ni sawa kwenye kila kifaa.",
    faq_a_new_me_week_challenge: "Changamoto ndogo ya wiki moja, unayoichagua mwenyewe. Kwenye ukumbi kuna kadi kubwa: “Ungependa kufanyia kazi nini wiki hii?” – iguse, chagua eneo (na nafsi yangu, na wengine, kujifunza na kukua, utulivu, hatua ndogo za ujasiri, nyumbani na ratiba) na changamoto, kisha chagua itaanza lini. Changamoto hizohizo pia ziko kwenye skrini ya changamoto, chini ya 🌱 Ukuaji binafsi. Kila siku weka ✓ kwenye kadi (siku moja huru kwa wiki), na kila wiki inayoisha huleta ufunguo mpya wa ulimwengu wa siri. “Kusoma kurasa 2 kwa siku” huwekwa alama yenyewe kutokana na kurasa zilizoandikwa kwenye Kona ya Kusoma. Wiki inapoisha, 📌 Iweke kama kazi ya kila siku inaiongeza kwenye Ratiba Yangu kwa saa unayochagua, na ✓ kila siku. Changamoto moja tu ya wiki huendelea kwa wakati mmoja; changamoto kubwa na ndogo huendelea pamoja nayo.",
    faq_a_room_genie: "Kwenye baraza linalotazama bahari, kugusa taa ya Aladini kunatoa roho ya msitu – na mazungumzo yanaanza: ombi lako ni lipi (ungependa kubadilisha nini maishani), litakavyojisikia likitimia, nini kigumu njiani, na hali ya sasa inawezaje kugeuzwa kuwa kitu kizuri. Kisha itachukua muda gani takriban, hatua ndogo ya kwanza na mbili zaidi, na “kama… basi…” kwa wakati utakapokuwa vigumu. Mwishoni ombi lote linaonekana hatua kwa hatua, na linaweza kuwa lengo kwenye Malengo Yangu (hatua huwa vituo vya njia, zikiwa na tarehe kulingana na muda uliochaguliwa; huko kila kitu kinaweza kubadilishwa) au kuhifadhiwa kwenye shajara – kisha roho inaaga. Hakuna kinachohifadhiwa usipochagua mojawapo. Kuanzia ziara ya pili, roho inauliza kwanza kama ungependa kubadilisha kitu kingine maishani mwako: ndiyo – mazungumzo yaleyale; si sasa hivi – ukumbusho wa kufikia malengo yaliyokwisha kuwekwa. Roho hutoka mara moja kwa siku: baada ya ombi kuhifadhiwa (au baada ya “Si sasa hivi”), inapumzika hadi kesho. Maswali yanafuata njia inayojulikana ya kugeuza ombi kuwa mpango: ombi, matokeo, kikwazo na mpango.",
    faq_q_books_home_chip: "Naweza kuona kitabu na ukurasa wangu kwenye skrini ya mwanzo?",
    faq_q_new_me_week_challenge: "Changamoto ya wiki ni nini?",
