    room_drawer_aria: "Kabati dogo",
    nm_me_choose: "Chagua",
    nm_me_on_screen: "Kwenye skrini",
    faq_a_new_me_game: "Ndani ya New Me vitufe vya mchezo hubaki mahali palepale kila wakati – kwenye ukumbi, kwenye chumba cha siri na kila mahali msituni; mchoro ulio katikati pekee ndio hubadilika. Juu: siku ya safari, funguo, mfululizo na nguvu ya leo (kiasi gani kimeliwa kutoka kwenye mpango), na chini yake jukumu linalofuata – mlo unaofuata kwa wakati wake (kuugusa kunaufungua, pamoja na ✓ Nimekula). Upande mmoja: siku nzima, changamoto na safari yangu, na kando yake changamoto ya wiki – siku zake 7 na ✓ ya leo. Chini: mkoba wa maajabu (kila kitu cha New Me – ramani ya dunia, safari yangu, ununuzi, mafanikio, shajara ya changamoto, vipimo, picha, kalenda ya mwezi, jedwali la siku, vikumbusho, PDF ya menyu na mipangilio; hufunguka kama skrini yake yenyewe). Ramani ya dunia, kitu cha kwanza ndani ya mkoba, inaonyesha kila mahali msituni – gusa mahali ili kwenda huko; mahali palipofungwa panaonyesha panahitaji funguo ngapi. Sky ni mhusika wako kwenye njia ya msituni: huanza kama Sky 1, baada ya changamoto chache (funguo 4) hukua na kuwa Sky 2 na karibu na mwisho (funguo 9) kuwa Sky 3 – kwa mabadiliko unayoweza kuyatazama yakitokea. Gusa Sky ili kuona kila hatua – hatua yoyote iliyokwisha kufikiwa inaweza kuchaguliwa tena, kwa hivyo ya awali inaweza kurudi. Sky huelea – huburutwa kwa kidole au kipanya, na mlango anaougusa hufunguka (mlango uliofungwa huonyesha funguo ngapi zinakosekana). Sky pia huja nawe katika kila chumba na kila mahali, na huelea popote unapomwacha: mburute popote, na uburute pete inayong'aa chini yake ili kumgeuza kabisa pande zote; hutazama upande anaoelekea (kwenye kompyuta: mishale humsogeza, Q na E humgeuza). Kwenye ukumbi, 🏠 ndogo chini ya upau wa juu hurudisha kwenye skrini ya mwanzo; katika kila chumba na mahali, kitufe kilicho kwenye kona ileile hurudisha kwenye ukumbi.",
    faq_q_new_me_game: "Vitufe vya mchezo, ramani ya dunia na Sky hufanyaje kazi?",
