    room_magic_song_rec3: "Vikengele vya maporomoko",
    faq_a_new_me_menu_build: "Kwanza dodoso linauliza unakula milo ipi na lini (Milo 2 + kitafunio, Milo 2 + chakula chepesi cha jioni, au vyote viwili), na kama kuna kitu jioni – cha kula au cha kunywa, nini, na saa ngapi. Kwa “Milo 2 + kitafunio”, milo ni chakula cha mchana (11:30) na chakula cha jioni (19:00), na kitafunio saa 16:00. Kisha chaguo zote za milo hiyo zinaonekana. Chagua vipendwa hadi 2 kwa kila mlo – menyu inaonyesha “hiki au kile”. Kwenye baadhi ya chaguo (pita na mpako, cornflakes na maziwa, kitu chepesi) unachagua hadi vitu 3 unavyopenda, kila kimoja kwa kiasi chake, na menyu inaonyesha “hiki au kile au kile”; kalori zinafuata ulichochagua. Kahawa na vinywaji hufanya kazi vivyo hivyo. Kila chaguo kimesawazishwa, kwa hivyo siku inafikia 1,300 au 1,500 sawasawa. Ili kubadilisha wakati wowote: ⚙️ Mipangilio → 🍽️ Tengeneza menyu yako, au “Chagua hadi 3 unavyopenda” kwenye kadi ya mlo.",
