    faq_a_myday_water_toggle: "Ndiyo. Glasi ya maji katika 'Siku Yangu' (na + kwa glasi moja zaidi) inaonekana kwa chaguo-msingi. Ili kuificha, zima \"Onyesha maji katika 'Siku Yangu'\" katika Mipangilio > Ubinafsishaji na Kalenda. Hakuna kinachofutwa – Ufuatiliaji wa Maji unaendelea kufanya kazi, na ukiwasha tena glasi inarudi.",
    faq_q_myday_water_toggle: "Je, naweza kuficha maji katika 'Siku Yangu'?",
    myday_water_toggle_label: "Onyesha maji katika 'Siku Yangu'",
    faq_a_routine_newme_sync: "Ukiwa na New Me, ⚙️ ya Ratiba Yangu ina swichi ya 'Sawazisha na New Me'. Ikiwa imewashwa (chaguo-msingi), milo ya New Me ya leo inaonekana kwenye Siku Yangu na kwenye Ratiba Yangu – mahali pa milo ya ratiba iliyofichwa. Ikiwa imezimwa, milo ya New Me inatoka sehemu zote mbili na ratiba inarudi kama ilivyokuwa kabisa. Hakuna kinachofutwa – kuiwasha tena kunarudisha kila kitu na kuuliza ni milo gani ya ratiba ya kuficha.",
    faq_q_routine_newme_sync: "Ninawashaje au kuzima usawazishaji wa New Me na Ratiba Yangu na Siku Yangu?",
