    theme_name_watercolor_wash: "Rangi za Maji",
    faq_a_food_list_languages: "Orodha ya vyakula iliyojengwa ndani ilianza na vyakula vya Israeli na majina yake ya Kiebrania. Katika lugha nyingine zote kila chakula kinaonyeshwa kwa jina lake la Kiingereza, na utafutaji unapata jina lolote la Kiingereza unalolijua (kwa mfano 'broth' inapata Clear soup); vyakula vyenye jina la Kiebrania pekee havionyeshwi. Chochote ambacho hakipo kwenye orodha unaweza kukiandika kwa maneno yako mwenyewe – makadirio ya AI yanafanya kazi katika kila lugha.",
    faq_q_food_list_languages: "Kwa nini orodha ya vyakula inaonyesha majina ya Kiingereza, na vyakula vichache, katika lugha yangu?",
    settings_copyright_line: "© 2026 haki zote zimehifadhiwa. programu imetengenezwa na eden zabari.",
    workout_ready_replace_btn: "Badilisha",
    faq_a_sport_workout_ai: "Katika \"Mazoezi yangu\" → ⋯ → \"Mpango kwa AI\" (na jedwali likiwa tupu, pia kwenye kigae karibu na mipango tayari). Jibu kwa migusano michache – mara ngapi kwa wiki, lini, mahali, kiwango na lengo, karibu yote pia yana \"Nyingine\" – na ukipenda ongeza mstari mmoja huru, kama goti nyeti au kukimbia km 5 kabla ya kiangazi. AI hupanga wiki nzima: aina za mazoezi, siku, saa, muda, ukali, mazoezi madogo na siku za kupumzika. Kabla chochote hakijahifadhiwa kuna onyesho la awali: \"Weka kwenye jedwali langu\" (badala ya jedwali au kama nyongeza), \"Pendekezo jingine\" (hadi mara 3) au \"Badilisha majibu\". Mpango ni wa wastani kwa makusudi, na ukitaja maumivu au jeraha unapata chaguo laini na ushauri wa kumuona mtaalamu. Hutumia kiasi kilekile cha AI kama ratiba na utaratibu: mara 5 bure, na mara 60 kwa mwezi ukiwa na Premium.",
    faq_q_sport_workout_ai: "Ninatengenezaje mpango wa mazoezi kwa AI?",
    workout_ai_add: "Ongeza kwenye jedwali langu",
    workout_ai_again: "Pendekezo jingine",
    workout_ai_apply: "Weka kwenye jedwali langu",
