    workout_ai_note_ph: "Kuna jambo la kujua? k.m. goti nyeti, au kukimbia km 5 kabla ya kiangazi",
    workout_ai_other: "Nyingine",
    workout_ai_replace: "Badala ya jedwali langu",
    workout_ai_title: "Mpango wa mazoezi kwa AI",
    workout_ai_when_evening: "Jioni",
