    workout_ai_when_morning: "Asubuhi",
    workout_ai_when_noon: "Mchana",
    workout_ai_when_ph: "k.m. baada ya kazi, au 17:30",
    workout_ai_working: "Mpango unaandaliwa…",
    faq_a_sport_workout_jar: "Kila aina ya zoezi ina nyota yake ya rangi – kukimbia waridi, kutembea kijani, kuogelea buluu na kadhalika. Kila zoezi linalorekodiwa wiki hii, kutoka kwenye jedwali au peke yake, hudondosha nyota yake ndani ya mtungi ulio juu ya \"Mazoezi yangu\", na mtungi hujaa kuelekea lengo lako la wiki (gusa ili kubadilisha lengo). Lengo likifikiwa, mtungi hung'aa. Mtungi mdogo kando yake huhesabu ni wiki ngapi mfululizo ulijaa.",
    faq_q_sport_workout_jar: "Nyota za rangi na mtungi katika \"Mazoezi yangu\" ni nini?",
    faq_a_sport_workout_gcal: "Ndiyo – katika ⋯ → Kalenda ya Google (baada ya kuunganisha Kalenda ya Google katika Mipangilio). Kila zoezi lenye saa linakuwa tukio linalojirudia kila wiki kwenye siku zake, na mabadiliko kwenye programu hulisasisha. Vikumbusho huja kutoka kwenye programu pekee, kwa hiyo Google haiongezi vyake, na mazoezi hayaonekani mara mbili kwenye programu. Kugusa tena huondoa kwenye Kalenda ya Google mazoezi pekee.",
    faq_q_sport_workout_gcal: "Je, mazoezi yangu yanaweza kuonekana kwenye Kalenda ya Google?",
    workout_gcal_btn: "Kalenda ya Google",
    workout_gcal_error: "Kalenda ya Google haikuweza kusasishwa – itajaribu tena kwenye badiliko lijalo",
    workout_gcal_not_connected: "Unganisha Kalenda ya Google katika Mipangilio kwanza",
    workout_gcal_off_toast: "Mazoezi yameondolewa kwenye Kalenda ya Google",
    workout_gcal_on_toast: "Mazoezi yako yako kwenye Kalenda ya Google",
    faq_a_sport_workout_reminder: "Ndiyo – ndani ya zoezi, Kikumbusho: dakika 10, dakika 30 au saa moja kabla, au muda wako (zoezi linahitaji saa). Hulia kama vikumbusho vingine, mara moja na mahali pamoja: kwenye programu ikiwa imefunguliwa, vinginevyo kwenye simu yako. \"Nimemaliza\" hurekodi zoezi kwenye historia, na \"Bado\" hukumbusha tena baada ya dakika 5.",
    faq_q_sport_workout_reminder: "Naweza kupata kikumbusho kabla ya zoezi?",
    workout_reminder_30min: "Dakika 30 kabla",
    workout_reminder_label: "Kikumbusho",
    workout_reminder_need_time: "Weka saa ili upate kikumbusho",
    faq_a_sport_workout_share: "Katika ⋯ → Shiriki, wiki inakuwa picha ya mtindo wa kioo kwa rangi za mandhari yako, pamoja na kiungo kidogo cha programu (kwenye simu inaenda moja kwa moja kwenye menyu ya kushiriki, kwenye kompyuta picha huhifadhiwa). ⋯ → PDF ya kuchapisha hufungua ukurasa safi wa wiki nzima, wenye kisanduku cha kuweka alama karibu na kila zoezi – chagua \"Hifadhi kama PDF\" au uchapishe. Mpango pia unaonekana kwenye ripoti ya data katika Mipangilio, sehemu ya Michezo.",
    faq_q_sport_workout_share: "Ninashirikije au kuchapisha wiki yangu ya mazoezi?",
    share_image_saved: "Picha imehifadhiwa – unaweza kuiambatisha",
    share_save_image: "Hifadhi picha",
    workout_pdf_btn: "PDF ya kuchapisha",
    workout_share_btn: "Shiriki",
    faq_a_sport_workout_board: "Katika ⋯ → Ubao wa wiki kila siku ni safu: buruta zoezi kwenda siku nyingine (kwenye simu, bonyeza na ushikilie kwanza). Ndani ya zoezi, \"Pia katika Ratiba Yangu\" hulituma kwenye ratiba yako kwa saa na siku zake, na mabadiliko hubaki sawa pande zote mbili; kutoka kipengele katika Ratiba Yangu, \"Ongeza kwenye mazoezi yangu\" hufanya kinyume. ✓ mahali popote huhesabiwa pande zote mbili, na katika Siku Yangu linaonekana mara moja tu – kwenye kibandiko karibu na maji.",
    faq_q_sport_workout_board: "Ninahamishaje zoezi kwenda siku nyingine, na kuliunganisha na Ratiba Yangu?",
    routine_in_workouts_btn: "Fungua kwenye mazoezi yangu",
    routine_to_workout_btn: "Ongeza kwenye mazoezi yangu",
    routine_to_workout_done: "Imeongezwa kwenye mazoezi yangu 💪",
    workout_delete_confirm_routine: "Litaondolewa kwenye mpango na kwenye Ratiba Yangu. Mazoezi yaliyorekodiwa kwenye historia yanabaki.",
    workout_moved: "Limehamishiwa {day}",
    workout_routine_need_time: "Weka saa ili kuliweka katika Ratiba Yangu",
    workout_routine_toggle: "Pia katika Ratiba Yangu",
    workout_view_board: "Ubao wa wiki",
    workout_view_timeline: "Mstari wa wakati",
    faq_a_sport_workout_plan: "Katika Ufuatiliaji wa Mazoezi, chini ya \"Mazoezi yangu\": + Zoezi – aina, siku, saa, muda, ukali na mahali (pia \"Nyingine\"). Mazoezi ya nguvu, ya kiutendaji na ya kuogelea yanaweza kuwa na orodha ya mazoezi madogo, na \"Kupumzika\" huweka alama ya siku ya kupumzika. Unaweza pia kuanza na mpango tayari. Zoezi la leo linaonekana kubwa, na wiki nzima chini yake; ✓ hulirekodi kwenye historia ya mazoezi pamoja na ukali wake. Katika ⋯ unaweka lengo la wiki (mazoezi au dakika) – kila zoezi unalofanya hudondosha nyota yake ndani ya mtungi.",
    faq_a_sport_workout_today: "Katika Siku Yangu, karibu na maji, kibandiko kidogo kinaonyesha zoezi la leo – ukikigusa hufungua maelezo, ✓ na ▶. ▶ huanzisha kipima muda kinachoendelea kwenye kibandiko cha skrini ya mwanzo, na \"Maliza\" hurekodi zoezi kwa muda halisi. Kama changamoto ya \"Wiki mbili za kusonga\" katika New Me inaendelea, zoezi lililorekodiwa huhesabiwa humo lenyewe.",
    faq_q_sport_workout_plan: "Ninapangaje wiki yangu ya mazoezi?",
