    dictation_lang: "Kuandika kwa sauti kwa lugha hii hakupatikani kwenye kivinjari hiki – jaribu Chrome",
    dictation_network: "Kivinjari hiki hakiwezi kufikia huduma yake ya kuandika kwa sauti – jaribu Chrome au Edge",
    dictation_no_mic: "Hakuna maikrofoni iliyopatikana – kompyuta inahitaji maikrofoni iliyounganishwa au vipokea sauti vyenye maikrofoni",
