    dictation_service_off: "Kuandika kwa sauti kumezimwa kwenye kivinjari au kompyuta hii – kuwashe kwenye mipangilio ya kompyuta, au jaribu Chrome",
    faq_a_new_me_magic_themes: "Mandhari tano zinazometameta zinazokuja na New Me: Msitu wa Kichawi, Vumbi la Nyota, Kichimbakazi cha Waridi, Mwanga wa Kichawi na Machweo ya Dhahabu. Chagua moja ndani ya New Me (⚙️ Mipangilio > Rangi) au kwenye Mipangilio > Muonekano na Skrini, na brashi ya kumetameta hupaka skrini kwa mandhari hiyo. Mandhari ya kichawi huongeza kumetameta kwenye programu nzima na kila unapogusa. Unaweza kurudi kwenye mandhari nyingine yoyote wakati wowote.",
