    theme_magic_section_label: "Mandhari za kichawi za New Me",
    apptour_focus_text: "Kila kitu kinakaa pembeni isipokuwa jambo moja la sasa – na ✓ kubwa. Kisha linalofuata linaonekana.",
    apptour_m_presets_text: "Milo yako iliyohifadhiwa mahali pamoja: tafuta, iliyotumika karibuni, kwa wakati wa siku – na ＋ huongeza mmoja kwa leo.",
    apptour_night_text: "🌙 hufanya programu yote kuwa giza; ☀️ hurudisha mchana.",
    apptour_noteline_text: "Andika na ugusa ➤ – inahifadhiwa kwenye madokezo yako. 📝 mwanzoni hubadilisha kuwa 🛒 manunuzi au 🍎 mlo uliohifadhiwa.",
    apptour_search_text: "Madokezo, manunuzi, kalenda, mapishi, madaftari, malengo, majedwali na vitabu – utafutaji mmoja unapata vyote.",
    faq_a_new_me_ai_menu: "Kabla ya menyu, dodoso linauliza unakula milo ipi na lini (milo 2 + kitafunio, milo 2 + chakula chepesi cha jioni, au vyote viwili), kama unakula kitu kidogo jioni na saa ngapi, usichokula, na unavyokunywa kahawa au chai. Kisha AI inaandaa chaguo 3 kwa kila mlo – kila moja kwa ukubwa wa sehemu ya mlo huo kwa siku, kwa hivyo jumla ya siku inabaki 1,300 au 1,500 kamili – pamoja na mawazo ya vinywaji, yanayohifadhiwa kama vinywaji vyako vya kudumu. Chagua vipendwa hadi 2 kwa kila mlo; chaguo za menyu asili ziko chini yake, na kwenye 🔄 Badilisha zinakuja baada ya menyu yako binafsi. 🔄 Chaguo nyingine huandaa seti mpya (mara 3 kwa kila dodoso). Ili kubadilisha majibu au kuandaa menyu mpya wakati wowote: ⚙️ Mipangilio → ✨ Menyu binafsi (AI).",
    faq_q_new_me_ai_menu: "Menyu binafsi ya New Me inafanyaje kazi?",
    nm_ai_menu_building: "Inaandaa menyu kulingana na milo na saa zako…",
    nm_ai_menu_drinks: "Vinywaji kwa ajili yako",
    nm_ai_menu_error: "Menyu binafsi haikuweza kuandaliwa sasa – hii ndiyo menyu asili. Unaweza kujaribu tena, au baadaye kutoka ⚙️ Mipangilio.",
