    apptour_s_gcal_inside_text: "Unganisha Google Calendar mara moja, na matukio na kazi vitabaki vikisawazishwa pande zote mbili.",
    apptour_s_menu_text: "Kila kitu unachoweza kurekebisha kiko hapa, katika makundi matano. Tuyafungue 👇",
    apptour_skip_part: "Ruka sehemu hii",
    apptour_start: "Anza ziara",
    nm_sales_premium: "Inajumuisha Premium yote",
    nm_unlock_premium: "Na Premium yote imefunguliwa pia.",
    settings_sub_status_newme: "Premium imejumuishwa kwenye New Me yako.",
    room_back_to_shelf: "Rafuni",
    faq_a_new_me_day_total: "Kila siku inafika sawasawa kwenye mpango: milo, takriban kalori 150 za kahawa na vinywaji wakati wa mchana, na kilichochaguliwa kwa jioni – kitu kidogo cha kula au kitu cha kunywa. Kwa jioni, chagua hadi 3 unavyopenda (kwa mfano ndizi, mtindi au vipande 2 vya chokoleti nyeusi; au chai ya mitishamba, chai yenye maziwa kidogo au maziwa ya moto), na kalori zake zinatolewa kwenye milo. Kila chaguo linajisawazisha lenyewe: chaguo dogo au kubwa zaidi, mlo ulioondolewa, kifungua kinywa kidogo na mlo mdogo unaokuja nacho, au jioni – tofauti inaongezwa kwenye milo au kutolewa, kila mmoja kulingana na ukubwa wake, na chini ya kila mlo imeandikwa kiasi gani (+ au −) na nini cha kuongeza au kuacha. Mlo uliokwisha wekewa alama unabaki kama ulivyorekodiwa. Kwenye dodoso, kila mlo unaonyesha marekebisho yake, na kisanduku kidogo kinaonyesha milo, vinywaji, jioni na jumla. Unatamani kitu kingine siku hiyo? Weka jumla kwenye kalori zile zile au chini.",
    faq_q_new_me_day_total: "Siku ya New Me inafikaje 1,300 / 1,500 kamili, na vinywaji vinahesabiwa wapi?",
    nm_budget_chosen: "Menyu iliyochaguliwa ~{n} · {adj} kwenye milo",
