    nm_swap_balanced: "Kalori {n} zinagawanywa kwenye milo, ili siku ifike {plan}",
    books_quotes_chip: "Nukuu",
    faq_a_book_quotes: "Kwenye rafu katika chumba cha siri (Nukuu), au kupitia kitufe kidogo 💬 Nukuu katika Kona ya Kusoma – ni orodha ileile. Gusa \"+ Nukuu\", andika sentensi na uchague kitabu kutoka Kona ya Kusoma, au andika jina jingine kwa \"✏️ Nyingine\"; mwandishi si lazima. ✏️ huhariri nukuu na 🗑️ huifuta. Nukuu ni alama za vitabu unazotelezesha – 🎨 juu hubadilisha kuwa picha au ukuta wa kadi.",
    faq_a_room_wish_jar: "Kwenye rafu katika chumba cha siri kuna chupa ya kioo kwa ajili ya ndoto. Gusa chupa ndogo kwenye rafu ya juu kabisa (au Rafu > Chupa ya matakwa) na uandike jinsi ungependa maisha yako yawe – kwa uhuru kadiri upendavyo, bila sahihi au kosa. Kila takwa hukunjwa kuwa karatasi na kuangukia chupani. \"Toa karatasi moja\" hufungua moja kwa nasibu, na kila karatasi inaweza pia kufunguliwa peke yake. Kuanzia mara ya pili unapofungua takwa lilelile, unaweza kulifanya lengo na kuligawa katika hatua ndogo. Mara moja kwa wiki, karatasi yenye mojawapo ya matakwa yako hujitokeza kwa upole – bila shinikizo, ni ukumbusho tu wa unakoelekea.",
    faq_q_book_quotes: "Nihifadhi wapi nukuu kutoka vitabu nilivyovipenda?",
