    room_wish_to_goal: "🎯 Ifanye lengo, kwa hatua ndogo",
    room_wish_written: "Imeandikwa {date}",
    faq_a_saved_meals_page: "Milo iliyohifadhiwa ina ukurasa wake: Lishe na Vipimo > ⭐ Milo iliyohifadhiwa (au ⭐ kwenye menyu). Utafutaji ulio juu hupata mlo kwa jina au kiungo, \"Iliyotumika karibuni\" huonyesha ulichoongeza hivi karibuni, na vichupo (Kifungua kinywa, Chakula cha mchana, Chakula cha jioni, Supu…) huonyesha kila wakati wa siku. \"+ Leo\" huongeza mlo kwenye Kifuatiliaji cha Chakula cha Kila Siku cha leo, kwenye nafasi tupu inayofuata. Gusa mlo ili kuuhariri au kuufuta, na ＋ juu huongeza mlo mpya.",
