    presets_tab_sweet: "Peremende",
    faq_a_notes_sticky_look: "Madokezo ni orodha fupi ya kadi za kioo – 🎨 juu ya Madokezo hubadilisha muonekano wa Madokezo yote: orodha, vitufe vya siku vilivyo juu na dirisha la kuandikia dokezo – kioo, orodha safi, kadi za kumbukumbu au utepe wa washi. Dokezo linalovutwa hubaki na muonekano na rangi yake hasa. Gusa maandishi ya dokezo ili kulifungua – hapo unaweza kulihariri, kubadilisha rangi zake na kuona lini liliandikwa mara ya mwisho. Gusa ○ likishafanyika, na × hulihamisha kwenye kumbukumbu (🗑️ chini ya orodha hulirudisha). Livute kwa ⠿ ili kubadilisha mpangilio, kulipeleka chini ya “Baadaye”, au kwenye siku iliyo juu. ! huweka alama kwamba dokezo ni la dharura – hupanda taratibu hadi kwenye mistari ya kwanza likiwa na lebo ndogo ya “Dharura”; mguso mwingine huiondoa.",
    faq_q_notes_sticky_look: "Ninafunguaje, kuhariri au kuondoa dokezo?",
    note_to_archive_btn: "Hamisha kwenye kumbukumbu",
    faq_a_routine_clash: "Ikiwa kwa saa hiyo, siku zile zile, tayari kuna kitu, kunakuwa na chaguo mbili: \"Badilisha\" – kitu kipya kinachukua saa hiyo na unachagua saa nyingine kwa kile kilichokuwepo (unapohariri kitu kilichopo, saa yake ya awali hupendekezwa, hivyo viwili vinabadilishana tu), au \"Vyote viwili\" – vyote vinabaki saa ile ile, kimoja chini ya kingine. Ikiwa siku ni tofauti (kwa mfano kimoja Jumapili–Alhamisi na kingine Ijumaa), hakuna kinachoulizwa.",
    faq_q_routine_clash: "Nini hutokea nikiweka kitu kwenye ratiba kwa saa ambayo tayari imeshikwa?",
    routine_clash_both: "✌️ Vyote viwili – vyote saa {time}",
    routine_clash_move_btn: "Hamisha na uhifadhi",
    routine_clash_move_to: "\"{title}\" ihamie saa ngapi?",
    routine_clash_replace: "🔄 Badilisha – na uhamishe \"{title}\" kwenda saa nyingine",
    routine_clash_title: "Saa {time} tayari kuna: {title}",
    faq_a_new_me_coffee: "Chini ya menyu ya leo kuna muhtasari mfupi: milo yote ya leo ina jumla ya kalori ngapi, kiasi kilichobaki kwa kahawa na vinywaji, na vitufe vya kahawa na vinywaji vilivyochaguliwa – mguso mmoja huongeza kwenye Vinywaji. Kwenye \"Chagua hadi 3 unavyopenda\" chini ya vitufe (na kwenye dodoso) chagua kinachoonekana: maji / maji ya soda, chai ya mitishamba, kinywaji cha diet, nyeusi / americano (~5), chai yenye maziwa kidogo (~25), kahawa ya maji yenye hadi ml 100 za maziwa au maziwa ya mimea (~50), chokoleti ya moto nyepesi, maziwa ya moto au kahawa ya kawaida / latte (~120).",
    faq_q_new_me_coffee: "Ninaongeza kahawa wapi, na nitajuaje kiasi kilichobaki kwa siku?",
