    nm_late_ideas_none: "Kumebaki kidogo sana leo – chai, maji au kahawa nyeusi",
    nm_late_room_line: "Kitu kidogo kabla ya kulala · zimebaki kalori ~{n} leo",
    faq_a_recipe_examples: "Chini ya mapishi yako mwenyewe kuna mapishi ya mfano: kifungua kinywa, saladi, supu, milo mikuu, vyakula vya kando, vitafunio, dessert na vyakula vya vegan, kila moja likiwa na muda wa maandalizi, kalori kwa mgao na uzito wa mgao mmoja kwa gramu. Gusa pishi ili kulifungua, na \"Hifadhi kwenye Mapishi Yangu\" huunda nakala yako mwenyewe unayoweza kuhariri. Lebo za kategoria huchuja, na kugusa lebo hiyo hiyo tena huonyesha yote.",
    faq_a_recipe_grams: "Ndani ya pishi, kando ya kalori, imeandikwa \"Mgao 1 ≈ gramu X\". Katika mapishi yako, jaza \"Gramu kwa kila mgao\" (na muda wa maandalizi ukipenda) kwenye fomu ya pishi: vyote viwili si lazima, na muda huonekana kwenye utepe wa rangi wa pishi.",
    faq_q_recipe_examples: "Mapishi ya mfano kwenye Mapishi Yangu ni nini?",
    faq_q_recipe_grams: "Nawezaje kuona mgao mmoja una gramu ngapi?",
    recipe_category_vegan: "Vegan",
    recipe_grams_placeholder: "Gramu kwa kila mgao",
    recipe_meta_grams: "Mgao 1 ≈ gramu {n}",
    recipe_meta_grams_short: "{n} g",
    recipe_meta_minutes: "dak {n}",
    recipe_minutes_placeholder: "Muda wa maandalizi (dakika)",
    recipe_save_example_btn: "Hifadhi kwenye Mapishi Yangu",
    recipe_saved_example: "✓ Imehifadhiwa kwenye Mapishi Yangu",
    recipe_saved_example_toast: "Imehifadhiwa kwenye Mapishi Yangu, unaweza kuyahariri huko",
    recipes_examples_title: "Mapishi ya mfano",
    faq_a_recipe_scan_multi: "Ndiyo. Katika \"Ongeza Mapishi\", gusa 📷 na uchague picha moja au kadhaa (hadi 6; PDF pia inafaa). Kila moja inaonekana kwenye orodha fupi ambapo unachagua kilichomo: Zote, Viungo au Maandalizi, na \"➕ Picha nyingine\" huongeza zaidi. Kisha gusa \"✨ Changanua mapishi\": AI inaunganisha kila kitu kuwa mapishi moja, kwa mpangilio na bila kurudia mistari, na inahesabiwa kama uchanganuzi mmoja. Picha kadhaa zilizochaguliwa kutoka 📷 Picha kwenye msaidizi wa AI pia hufunguka hapa.",
    faq_q_recipe_scan_multi: "Je, ninaweza kuchanganua mapishi moja kutoka picha kadhaa, kwa mfano viungo na maandalizi kando, au kurasa mbili?",
    recipe_scan_add_more: "➕ Picha nyingine",
