    recipe_scan_run_btn: "✨ Changanua mapishi",
    recipe_scan_too_many: "Hadi picha {n} kwa kila mapishi",
    faq_a_note_written_at: "Gusa maandishi ya kidokezo ili kukifungua. Ndani, chini ya maandishi, inaonyesha kiliandikwa lini mara ya mwisho, kwa tarehe na saa sahihi. Kubadilisha maandishi yenyewe tu ndiko kunakosasisha hili: kuweka kwenye kumbukumbu na kurejesha, kuweka ✓, rangi au kukihamisha hakubadilishi.",
    faq_q_note_written_at: "Nawezaje kuona nilipoandika kidokezo?",
    note_written_at: "Iliandikwa mara ya mwisho: {date}",
    faq_a_new_me_month: "Kwenye mkoba wa maajabu → Kalenda ya mwezi: kila siku ina rangi kulingana na milo mingapi ilitiwa alama, mishale ‹ › inahamia kati ya miezi, na chini ya kalenda kuna wastani wa kalori kwa siku wa mwezi huo. Kugusa siku kunaonyesha milo mingapi ilitiwa alama na kalori ngapi zililiwa siku hiyo.",
    faq_q_new_me_month: "Kwenye New Me ninaona wapi mwezi uliopita na wastani wa kalori?",
    nm_month_avg: "Wastani wa mwezi: kalori {kcal} kwa siku · siku zilizorekodiwa: {n}",
    nm_month_day_empty: "Hakuna kilichorekodiwa siku hii.",
    nm_month_day_line: "Milo iliyotiwa alama: {checks} · kalori: {kcal}",
    nm_extra_line_small: "Kalori {n} kwa mlo huu, kutoka kwa kifungua kinywa kidogo – kwa mfano {ideas}",
    faq_a_new_me_small_breakfast: "Kifungua kinywa chepesi (takriban kalori 170): pita ya spelt (hadi kalori 100) na mpako au jibini, na pia mboga moja – chagua hadi 3 unavyopenda, kwa mfano kijiko 1 kidogo cha chokoleti ya kupaka, kijiko 1 kidogo cha siagi ya karanga au kipande cha jibini gumu (mafuta hadi 22%). Kwa kuwa ni kidogo, “Pamoja na mlo mdogo” huja nacho kwa saa nyingine (saa moja na nusu baadaye, kwa mfano 11:30 → 13:00 – saa nyingine yoyote inaweza kuchaguliwa): pita nyingine na mpako, mtindi wa protini na tunda, vidakuzi vya mchele na jibini, nafaka na maziwa au nusu pita na mayai – hadi takriban kalori 200, wenye ✓ yake. Kinachobaki bado kinagawanywa kwa milo mingine, na kila mlo unaonyesha kiasi kilichoongezwa, hivyo jumla ya siku inabaki kama kwenye mpango. Chagua kwenye dodoso, au ubadilishe kwenda kwake kwa leo tu kwa 🔄 – kwa mfano kifungua kinywa kikichelewa.",
    faq_q_new_me_small_breakfast: "\"Kifungua kinywa kidogo\" kwenye menyu ya New Me ni nini?",
    home_note_meal_ai: "✨ Kokotoa kwa AI",
    home_note_meal_none: "Hakuna mlo uliohifadhiwa kwa jina hilo",
    myday_earlier: "Mapema",
    nm_ing_spelt_pita: "Pita za spelt",
    nm_ing_spread: "Mpako (chokoleti / siagi ya karanga / tahini mbichi)",
