    weather_sky_rain: "Mvua",
    weather_sky_snow: "Theluji",
    weather_sky_storm: "Dhoruba",
    faq_a_ai_icon: "Ndiyo – katika Mipangilio > Muonekano na Skrini. Kiputo laini ndicho cha msingi, na ukiwa na Premium unaweza pia kuchagua ubongo unaoelea au roboti.",
    faq_a_new_me_favorites: "Ndiyo. Katika dodoso (na unapolijaza tena kutoka mipangilio) unaweza kuchagua hadi chaguo 2 kwa kila mlo. Cha kwanza kinaonekana kwenye menyu, na chini yake kuna mstari wa “au” wa cha pili – ukiugusa unabadilisha kwenda kwake kwa leo tu. Na kama kifungua kinywa hakikuliwa kwa wakati, “⏰ Baadaye” kinakisogeza hadi baadaye siku hiyo, bila kubadilisha kalori.",
    faq_a_theme_mode: "Baadhi ya mandhari maalum zinapendeza zaidi kwenye giza – Rangi za Maji, Aurora, Barbie na mandhari mbili za kumetameta – kwa hivyo kuchagua moja wapo kunabadilisha programu kwenda hali ya giza, na kuchagua mandhari nyingine yoyote (pamoja na roketi) kunaibadilisha kwenda mwanga. Nyeusi na Kijivu Iliyokolea zinabaki giza. Unaweza kubadilisha wakati wowote baadaye kwa 🌙 kwenye menyu au kwa Hali ya Mwanga kwenye mipangilio.",
    faq_a_water_month: "Katika ufuatiliaji wa maji. Kila ingizo kwenye rekodi ya leo linaonyesha saa lilipoongezwa, na \"Jedwali la mwezi\" linafungua mwezi mzima: kila siku inaonyesha lita ngapi zilinywewa (✓ lengo la siku lilipofikiwa), na kugusa siku kunaonyesha maingizo yake pamoja na saa zake.",
    faq_q_ai_icon: "Je, ninaweza kubadilisha ikoni ya msaidizi wa AI?",
    faq_q_new_me_favorites: "Je, ninaweza kuchagua chaguo mbili ninazopenda kwa mlo mmoja katika New Me?",
    faq_q_theme_mode: "Kwa nini programu ilibadilika kuwa giza (au mwanga) nilipochagua mandhari?",
    faq_q_water_month: "Ninaona wapi kiasi cha maji nilichokunywa kila siku?",
