    dev_sim_panel_title: "PM – kwa ajili yako tu",
    faq_a_new_me_weight_optional: "Hapana. Uzito wa sasa na uzito lengwa kwenye dodoso si lazima. Ukipima uzito baadaye (⚖️ Uzito katika \"Safari yangu\" ndani ya New Me, au kwenye kifuatiliaji cha uzito), maendeleo huhesabiwa kuanzia kipimo cha kwanza.",
    faq_q_new_me_weight_optional: "Je, ni lazima kuandika uzito katika New Me?",
    nm_unlock_desc: "Menyu, changamoto na safari viko tayari – hatua kwa hatua, pamoja.",
    nm_unlock_title: "New Me imefunguliwa!",
    room_reveal_star: "Nyota mpya imewaka kwenye darubini juu ya paa ✨",
    faq_a_room_records: "Kicheza santuri kiko chumbani tangu mwanzo, juu ya kisiki cha mti karibu na kiti cha mikono. Santuri zake hufungua video rasmi za nyimbo kubwa maarufu za miaka ya karibuni kwenye YouTube, na chini yake kuna nyimbo tano tulivu zinazopigwa hapa chumbani – santuri huzunguka zinapopigwa, na \"⏹ Simamisha\" huzima muziki.",
    faq_a_room_roof_gifts: "Vinakuja na ufunguo wa 8. Kugusa darubini hukuruhusu kuchungulia ndani yake: anga la usiku kwa karibu – buruta (au tumia mishale) kutazama pande zote – na changamoto ulizokamilisha huchora kundinyota ndani yake, nyota moja kwa kila changamoto; kugusa nyota huonyesha ilikuwa changamoto gani. Kugusa sanduku dogo hulifungua – kwa sasa liko tupu – na mguso mwingine hulifunga.",
    faq_q_room_records: "Kuna nini kwenye kicheza santuri katika chumba cha siri?",
    faq_q_room_roof_gifts: "Darubini na sanduku lililo juu ya paa ni nini?",
    room_chest_letter: "Barua ndogo kwa ajili yako",
    room_chest_letter_1: "Kila hatua ndogo njiani ilikuwa ya kweli – na kila moja ina maana.",
    room_chest_letter_2: "Kujihurumia ni sehemu ya njia, si mapumziko kutoka kwayo.",
    room_chest_letter_3: "Kuna siku nyepesi na siku nzito. Kuwepo katika zote mbili ndiyo nguvu halisi.",
    room_chest_letter_4: "Kupumzika kunaruhusiwa. Kupumzika pia ni hatua mbele.",
    room_chest_letter_5: "Mabadiliko yanayodumu ni yale ya kimya – hujengwa siku baada ya siku.",
    room_chest_letter_6: "Leo ni siku nzuri ya kujivunia – hata kidogo tu.",
    room_chest_letter_7: "Hakuna haja ya kufanya kila kitu. Kitu kidogo kinachofuata tu.",
    room_chest_letter_8: "Lolote lililotokea jana, leo ni mwanzo mpya.",
    room_chest_locked: "Siku 3 mfululizo zenye ✓ hufungua sanduku · {n}/3",
