    dev_sim_lock: "Funga – ona kama kabla ya kununua",
    dev_sim_locked_toast: "🔒 Imefungwa – hivi ndivyo inavyoonekana kabla ya kununua",
    faq_a_new_me_preview: "Ndiyo. Ukurasa wa New Me unaanza na video fupi ya kinachotokea ndani: dodoso, taa za ukumbini, mkoba wa maajabu, changamoto na funguo. Chini yake kuna kila kitu kilichojumuishwa, mfano wa siku moja na majibu mafupi.",
    faq_q_new_me_preview: "Je, naweza kuona New Me kabla ya kununua?",
    nm_trailer_c1: "Dodoso fupi – na menyu yako iko tayari",
    nm_trailer_c2: "Kila mlo ni taa katika ukumbi wako",
    nm_trailer_c3: "Ndani ya mkoba wa maajabu: menyu ya leo, maji na manunuzi",
    nm_trailer_c4: "Maliza changamoto ndogo – pata ufunguo",
