    ai_chat_food_edit: "✏️ Rekebisha kalori / protini",
    ai_chat_food_invalid: "Kalori lazima ziwe namba kubwa kuliko 0",
    ai_chat_food_updated: "Imesasishwa:",
    faq_a_ai_chat_food_fix: "Ndiyo. Chini ya jibu kwenye gumzo, gusa ✏️ Rekebisha kalori / protini, badilisha namba kisha gusa Hifadhi. Kinachobadilika ni kile kilichoongezwa sasa hivi tu – hata kama kiliunganishwa na kitafunio kilichokuwepo. AI inaweza kukosea, kwa hiyo ni vizuri kuangalia haraka.",
    faq_a_new_me_home_btn: "Ukiwa na New Me, 💎 ndogo kando ya hali ya umakini juu ya skrini ya mwanzo hufungua menyu ya leo. Milo ya leo pia inaonekana katika Siku Yangu, kila mmoja ukiwa na ✓.",
    faq_a_routine_item_days: "Ndiyo. Gusa kipengele katika Ratiba Yangu na uchague siku zake chini ya 📅 Siku – kwa mfano Jumatatu hadi Ijumaa tu. Siku nyingine hakionekani katika Siku Yangu na hakina ✓; katika Ratiba Yangu kinabaki, kikiwa hafifu zaidi, na siku zake kando yake. Kadi inayouliza kuhusu kipengele baada ya siku 3 bila ✓ huhesabu siku za kipengele hicho tu.",
    faq_q_ai_chat_food_fix: "Je, naweza kurekebisha kalori au protini baada ya msaidizi kurekodi chakula?",
    faq_q_new_me_home_btn: "New Me iko wapi kwenye skrini ya mwanzo?",
    faq_q_routine_item_days: "Je, kipengele kimoja katika Ratiba Yangu kinaweza kuwa siku fulani tu?",
    routine_item_days_label: "📅 Siku",
    home_note_meal_ph: "Tafuta mlo uliohifadhiwa…",
    menu_quick_search: "Utafutaji wa haraka",
    nm_times_hint: "Kidokezo: unaweza kuweka saa ya mwisho kabisa unayokula kila mlo kwa kawaida – kwa mfano 9:00 ikiwa mara nyingi unakula karibu saa 8.",
    room_game_marquee: "Njiani – simama ufurahie",
    room_sand_erase_aria: "Sugua ili kufuta maandishi",
    faq_a_home_note_line: "Andika kwenye mstari ulio katikati ya skrini kuu kisha gusa ➤ (au Enter) – linahifadhiwa kwenye Maelezo. Gusa 📝 mwanzoni mwa mstari nalo linakuwa 🛒: kisha unachoandika kinaenda kwenye Orodha ya Ununuzi. Gusa mara moja zaidi kupata 🍎: andika herufi chache, milo yako iliyohifadhiwa inayolingana itaonekana, na mguso mmoja unaandika mmoja kwenye milo ya leo. Kwa 🎤 unaweza kusema tu kwa sauti.",
    faq_a_night_mode: "Fungua menyu ☰ kisha gusa 🌙 juu – programu yote inakuwa giza. ☀️ mahali hapo hapo inarudisha mchana. Pia iko kwenye Mipangilio, chini ya Hali ya Mwanga.",
    faq_q_home_note_line: "Ninaandikaje dokezo la haraka kutoka skrini kuu?",
    faq_q_night_mode: "Ninabadilishaje kwenda hali ya usiku?",
    menu_day_mode: "Hali ya mchana",
    menu_night_mode: "Hali ya usiku",
    faq_a_secret_room_yoga: "Mwisho wa njia ya msituni kuna lango linalong'aa, na nyuma yake, karibu na maporomoko ya maji, viumbe wa msituni – Lumi, Puffi, Nixie na Sparklet – wameketi juu ya mikeka yao katika nusu duara, na Flora, mwalimu wa yoga, ameketi akiwatazama kwenye mkeka wa pekee ulio juu ya jiwe. Gusa Flora: anafumbua macho, kila kitu kinasogea karibu, na mazungumzo yanaanza polepole, kwa muda wa kusoma – Flora anauliza hali ya kila mtu, kila kiumbe hujibu kwa sauti yake mwenyewe (kando ya kila mstari kuna picha ndogo ya anayezungumza), kisha anakuuliza unajisikiaje ukiwa na watu wako wa karibu. Mazungumzo yanaendelea kulingana na majibu yako – watu wema, mtu aliye mgumu, au upweke kidogo. Kila njia inaishia na kazi ndogo (inaweza kwenda moja kwa moja kwenye Siku Yangu; kazi ikiwa ni kuandika kitu, kuna nafasi ya kuandika, na kinahifadhiwa kwenye shajara ya maajabu) na mkao wenye pumzi tatu pamoja. ↩ inarudi hatua moja na ✦ inaanza mazungumzo mapya. Ufunguo unaofuata unafungua maporomoko ya maji: ukiketi juu ya jiwe, kila kitu kinatoweka na sauti ya maji pekee inabaki. Ukiinama juu ya bwawa, swali huibuka kutoka majini – wewe halisi ungefanya nini leo? – na jibu linakuwa kazi ndogo katika Siku Yangu. Ni wakati mzuri, si mbadala wa kuongea na mtaalamu.",
    faq_q_secret_room_yoga: "Nini hutokea kwenye yoga ya msituni?",
    room_back_to_forest: "Rudi kwenye njia",
    room_back_to_yoga: "Rudi kwenye yoga",
