    yg_g_alone: "Asante kwa kushiriki. Hutokea kwa kila mtu wakati mwingine.",
    yg_g_alone_q: "Nini kingejisikia sawa, hata kidogo tu?",
    yg_g_critic: "Kukosolewa kunaweza kuuma kwa muda mrefu. Kunahusu wakati mmoja – si utu wote wa mtu.",
    yg_g_end: "Asante kwa kuja kwenye duara. Unaweza kurudi wakati wowote.",
    yg_g_gate: "Ni sawa kuweka mpaka. Mpaka si ukuta – ni lango.",
    yg_g_good: "Inapendeza sana 💛 Nani amekufanyia mema wiki hii?",
    yg_g_good_msg: "Watu wema wanastahili kuambiwa. Asante ndogo inaweza kuifanya siku yao yote.",
    yg_g_hard: "Asante kwa kusema. Ni nini kinachokulemea zaidi?",
    yg_g_listen: "Kutosikilizwa kunachosha. Sauti yako ni muhimu, hata ikiwa ya chini.",
    yg_g_new: "Watu wapya huanza na salamu ndogo. Darasa, matembezi, kikundi – hatua moja.",
    yg_g_old: "Mtu anayekujua tayari ni mahali penye joto. Ujumbe mfupi unatosha.",
    yg_g_start: "Na sasa ni zamu yako 🌿 Siku hizi unajisikiaje ukiwa na watu wako wa karibu?",
    yg_g_used: "Tunapotoa bila kupata chochote, kitu ndani huchoka. Ni sawa kukitambua.",
