    yg_pose_child: "Sasa mkao wa mtoto 🌙 Magoti chini, paji la uso kwenye mkeka – mahali salama pa kupumua. Pumzi tatu pamoja.",
    yg_pose_heart: "Sasa moyo wazi 💗 Mabega nyuma, kifua kipana. Pumzi tatu pamoja.",
    yg_pose_tree: "Sasa mkao wa mti 🌳 Simama imara, mguu mmoja juu ya mguu mwingine, mikono juu. Pumzi tatu pamoja.",
    yg_task_good: "Kutuma ujumbe mdogo wa shukrani leo",
    yg_task_hard: "Kuandika sentensi moja ningependa kusema",
    yg_task_new: "Kutafuta mahali pamoja pa kukutana na watu wapya",
    yg_task_old: "Kumtumia mtu \"Nimekuwaza\"",
    nm_time_hour: "Saa",
    nm_time_minutes: "Dakika",
    routine_time_taken: "Tayari kuna kitu saa hii: {title}",
    faq_a_new_me_times: "Kwenye dodoso la mwanzo, na wakati wowote kwenye mipangilio ya New Me → \"Saa za milo\". Ikiwa ratiba yako tayari ina saa za milo, zinachukuliwa kutoka hapo – na milo ya ratiba inaweza kufichwa, na milo ya New Me ikaonyeshwa mahali pake. Ikiwa haina, chagua milo mingapi kwa siku (Milo 2 + kitafunio / Milo 2 + chakula chepesi cha jioni / Milo 2 + kitafunio + chakula chepesi cha jioni) na kila mmoja ni saa ngapi. Kwa \"Milo 2 + kitafunio\" ni chakula cha mchana saa 11:30, kitafunio saa 16:00 na chakula cha jioni saa 19:00 (kila kimoja kinaweza kubadilishwa). Hizi ndizo saa zako za milo kila mahali: kwenye ukumbi, kwenye Siku Yangu, kwenye Ratiba Yangu na kwenye vikumbusho. Chochote kitakachochaguliwa, kalori za siku hubaki zile zile: kilichoondolewa hugawanywa kwa milo mingine.",
    faq_q_new_me_times: "Ninawekaje saa zangu za milo kwenye New Me?",
    nm_times_count: "Milo mingapi kwa siku?",
    nm_times_from_routine: "Ndiyo, chukua kutoka kwenye ratiba yangu",
    nm_times_hide: "Ficha milo ya ratiba yangu na uweke milo ya New Me mahali pake",
    nm_times_later: "Baadaye",
    nm_times_manual: "Hapana, chagua hapa",
    nm_times_none_found: "Ratiba yako bado haina milo – chagua hapa ni mingapi na lini.",
    nm_times_q: "Je, ratiba yako ina saa maalum za kula?",
    nm_times_saved: "Saa za milo zimehifadhiwa",
    nm_times_title: "Saa za milo",
    faq_a_routine_exact_time: "Ndiyo. Unapoieleza AI utaratibu wenye saa kamili (kama \"16:10 biashara\"), huhifadhiwa hivyo hasa – bila kuzungushwa kuwa saa nzima. Chochote kilichoandikwa kwenye utaratibu wako huonekana kwenye ubao kila wakati, hata kama saa yake haijachaguliwa kwenye mipangilio ya saa, na kuondoa saa yenye kitu ndani yake huuliza kwanza. Unaweza pia kubadilisha saa kwa mkono: gusa saa kwenye dirisha la kipengee kisha uchague saa na dakika.",
    faq_q_routine_exact_time: "Je, utaratibu wangu unaweza kuwa na saa kamili, kama 16:10?",
