    routine_daysoff_which: "Siku zipi?",
    faq_a_secret_room_diary: "Wewe peke yako. Kurasa za shajara huhifadhiwa kwenye akaunti yako, kwa hiyo zipo kwenye kila kifaa, na hakuna mtu mwingine anayeweza kuziona. Shajara ya maajabu iliyo juu ya meza katika chumba cha siri huifungua, na pia shajara iliyo kwenye kona ya muziki. Chini ya ukurasa mpya kuna jedwali la mwezi lililokunjwa: nukta huonyesha kila siku yenye ukurasa, na kugusa siku hufungua kurasa zake – hapo pia unaweza kufuta ukurasa. Shajara ikishafunguka, inaweza pia kuongezwa kwenye menyu kuu – kwa swichi iliyo ndani ya shajara yenyewe au kwenye mipangilio ya New Me.",
    faq_a_secret_room_places: "Kila kiingilio kwenye lango la msitu hufunguka kwa ufunguo wake. Nyuma yake: baraza linalotazama bahari (juu ya meza ndogo taa ya Aladini – gusa, na roho ya msitu hutoka ndani yake katika ukungu wa maajabu, huzunguka na kuanzisha mazungumzo kuhusu ombi lako – tazama “Jini wa taa hufanya nini?”), gitaa na shajara (gitaa hupiga wimbo mfupi tulivu na kujisimamisha lenyewe, na kila moja ya santuri tatu zinazoning'inia kwenye mti hupiga wimbo wake wa maajabu – gusa tena kusimamisha – na shajara iliyo juu ya kisiki ni ya kuandika), chumba cha kupumua (ziwa tulivu wakati wa machweo – taa ya lotasi huelea juu ya maji: iguse, andika matakwa, nayo huondoka nayo, mbali ndani ya ziwa; kwa fimbo ya miujiza unaweza kuandika mchangani kile unachotaka kuachilia, nacho hubaki hadi ukifute kwa kidole) na njia ya msituni (hufunguka usiku, na kugusa taa huibadilisha kuwa mchana; kutoka tawi kubwa hutundikwa bembea ya maajabu, benchi ni ya kukaa, na kugusa kibao hukisogeza karibu – ubao wenye maswali sita madogo ya kuweka alama). Kiingilio kilichofungwa huonyesha funguo ngapi zimebaki. Mwisho wa njia, lango linalong'aa linaelekea kwenye yoga karibu na maporomoko ya maji – na kutoka hapo, kwenye maporomoko yenyewe.",
