    ai_chat_working_table: "Subiri kidogo, natengeneza jedwali…",
    dev_weather_preview_label: "Hakiki – kwenye akaunti yako tu:",
    faq_a_ai_chat: "Gusa kiputo na mazungumzo yatafunguka. Chagua cha kufanya – kitu cha kalenda, ulichokula, picha ya mapishi au jedwali jipya – au andika tu, na msaidizi atatambua mwenyewe. Unaweza pia kugusa 🎙️ na kuzungumza badala ya kuandika. Kwa kalenda unaweza kuchagua mara moja, kila wiki au kila siku. Jibu linakuja kwenye mazungumzo, na kutoka hapo unaweza kuendelea na kitu kingine au kufungua kalenda / ulichokula.",
    faq_a_new_me_hall: "New Me hufunguka kwenye lango la msitu wa maajabu, na kila kiingilio ndani yake ni mahali: mlango wa duara kwenye mti mkubwa mno unaingia kwenye chumba cha siri, gogo lenye mvungu – kwenye baraza linalotazama bahari, nyumba ya uyoga – kwenye gitaa na shajara, tao dogo la mierebi – kwenye chumba cha kupumua, tao kubwa la mierebi – kwenye njia ya msituni, na tao la maua lenye ngazi hupanda hadi paa la nyota linapofunguka. Kiingilio kilichofungwa kina kufuli. Kwenye njia huelea mhusika wako, Sky, na vitufe vya mchezo viko pande zote: jukumu linalofuata, changamoto ya wiki, mkoba wa maajabu wenye New Me yote, ramani ya dunia na zana. Kugusa funguo zilizo juu kunaeleza jinsi funguo zinavyopatikana.",
    faq_a_new_me_routine_meals: "Milo ikiwa imepangwa kwenye New Me na Ratiba Yangu ina milo pia, New Me inauliza kama iifiche na kuonyesha milo ya New Me mahali pake – ili hakuna kitu kionekane mara mbili. Kisha Ratiba Yangu inaonyesha milo ya New Me kwa saa zake, pamoja na 💎 na ✓; kugusa jina la mlo kunafungua dirisha la kuchagua mlo mwingine au kubadilisha saa yake, papo hapo juu ya ratiba. Hakuna kinachofutwa: inarudi kupitia ⚙️ Mipangilio ya New Me → Milo kwenye ratiba, au kwa kuzima “Sawazisha na New Me” kwenye ⚙️ ya Ratiba Yangu. Bila New Me inayotumika, inarudi yenyewe.",
    faq_a_room_computer: "Ni mazungumzo mafupi yanayoanza na “Siku yako inaendaje hadi sasa?” – nzuri, yenye shughuli nyingi au ngumu – kisha yanaendelea nawe hatua kwa hatua, hadi jukumu moja dogo mwishoni (ambalo pia linaweza kuingia moja kwa moja kwenye Siku Yangu). Majibu yanaweza kuguswa au kuandikwa kwa uhuru – kinachoandikwa kinaunganishwa na jibu lililo karibu zaidi. “↩ Rudi” inarudi hatua moja ili kujibu tofauti, na “Mazungumzo mapya” yanaanza upya wakati wowote. Baada ya siku yenye shughuli nyingi au ngumu, unaweza kurudi kwenye kompyuta baadaye siku hiyo hiyo: “Nimerudi...” inaendeleza mazungumzo. Taa ya kijani chini inazima na kuwasha kompyuta. Ni chaguo tu zinazohifadhiwa, kwenye kifaa hiki tu na hadi mwisho wa siku tu.",
    faq_q_ai_chat: "Nazungumzaje na msaidizi?",
    faq_q_new_me_hall: "Ukumbi ndani ya New Me ni nini?",
    faq_q_new_me_routine_meals: "Kwa nini Ratiba Yangu inaonyesha milo ya New Me?",
    faq_q_room_computer: "Kompyuta ya chumba cha siri inafanyaje kazi?",
