    dictation_btn_aria: "Ongea, na itaandikwa",
    dictation_mic_denied: "Maikrofoni imezuiwa – iruhusu kupitia 🔒 kando ya anwani kwenye kivinjari, au kwenye mipangilio ya simu",
    faq_a_dictation: "Ndiyo – gusa maikrofoni 🎤 kwenye kona ya kidokezo cha haraka au ukurasa wa kuandika kwenye daftari, kisha ongea: maneno huandikwa unapoongea, kwa lugha ya programu. Gusa tena ili kusimamisha. Mara ya kwanza, kivinjari huomba ruhusa ya kutumia maikrofoni. Hufanya kazi kwenye Chrome / Android na Safari kwenye iPhone. Kwenye kompyuta unahitaji maikrofoni na kivinjari kama Chrome, Edge au Safari – kikikosekana kitu, ujumbe husema ni nini hasa.",
    faq_q_dictation: "Je, naweza kuongea badala ya kuandika?",
    faq_a_secret_room: "Chumba ambacho ni chako peke yako, ndani ya New Me – nyumba ndani ya mti mkubwa mno. Unaona ukuta mmoja kwa wakati na unageuka kwa mishale (au kwa kutelezesha). Ufunguo wa kwanza huja baada ya ✓ kwenye mlo katika siku 3 tofauti na hufungua mlango – pamoja na chumba chote: kompyuta, mchezo, kicheza santuri, rafu yenye maktaba ndani yake na paka. Kisha kila changamoto inayokamilika (pamoja na changamoto ya wiki) hutoa ufunguo unaofungua mahali panapofuata: paa la nyota, baraza linalotazama bahari, gitaa na shajara, chumba cha kupumua, njia ya msituni pamoja na yoga, maporomoko ya maji na mshangao juu ya paa – na changamoto ya 8 huleta chupa kutoka baharini, ikiwa na barua kutoka zamani ndani yake. Kitu kinapofunguka, mshale huonyesha njia ya kufika huko. Mlango mdogo chini ya mashine ya mchezo nao hufunguka – kwa sasa kabati lililo nyuma yake ni tupu. Juu ya paa la nyota, nyota uliyoigusa huanguka kama kimondo, na paka ameketi juu ya mto.",
