    settings_good_things_label: "\"Mambo 3 mazuri\" jioni",
    settings_weather_hint: "Mvua, mawingu au theluji kwenye mandharinyuma ya skrini ya nyumbani, kulingana na hali ya hewa ulipo. Mahali pako kwa makadirio hubaki kwenye kifaa hiki na huangaliwa kupitia seva yetu kwa MET Norway.",
    settings_weather_label: "Hali ya hewa kwenye anga la skrini ya nyumbani",
    weather_failed: "Imeshindikana kuangalia hali ya hewa sasa hivi.",
    weather_location_denied: "Hakuna ruhusa ya mahali – iruhusu kwenye mipangilio ya kivinjari kisha ujaribu tena.",
    faq_a_home_focus: "Gusa ◎ juu ya skrini ya nyumbani: kila kitu kinatoweka isipokuwa jambo moja la sasa – kilichopo saa hii, au kinachofuata kwenye orodha ya leo – pamoja na ✓ kubwa, na Maelezo ya Haraka. Baada ya ✓, kinachofuata kinaonekana. Gusa 'Hali ya umakini ✕' juu ili kila kitu kirudi.",
    faq_a_home_search: "Fungua menyu ☰ – utafutaji uko juu kabisa. Andika angalau herufi 2: matokeo yanatoka kwenye maelezo, orodha ya ununuzi, kalenda, mapishi, madaftari (vichwa na maandishi ya kurasa), malengo, majedwali na vitabu vyako, yakiwa yamepangwa kwa aina – gusa moja kwenda moja kwa moja huko.",
    faq_a_my_day: "Siku Yangu inaunganisha kile kilichokuwa Mtazamo wa Leo na Ratiba Yangu kwenye mstari mmoja wa wakati. Chini ya skrini ya nyumbani unaona kiasi kilichofanyika, kilichopo sasa au kinachofuata (pamoja na ✓ ya haraka), na kando ya kichwa glasi ya maji kwa +1. Gusa (au telezesha juu) ili kufungua siku nzima: juu kuna vitu visivyo na saa, kisha kila kitu kwa saa – kazi, matukio na mikutano ya kalenda, nafasi za kudumu za kila wiki, ratiba ya leo, hatua ndogo za malengo yako na milo ya New Me – pamoja na mstari wa sasa. Chuja kwa Kazi, Ratiba au Mikutano na matukio. ✓ hapa ni ✓ ile ile kila mahali pengine (Ratiba Yangu, Malengo Yangu, kalenda) na inachanua ua la daisi kwenye kona. 'Hariri ratiba' inafungua Ratiba Yangu (iko pia kwenye menyu), na '＋ Ongeza kwa leo' inaongeza kazi ya leo. Kugusa kichwa \"Siku Yangu\" (au kibao kidogo juu) kunaifunga tena.",
