    faq_a_table_shopping_link: "Katika safu ya ✓ iliyounganishwa na orodha ya ununuzi (kama 'Viungo vipo' katika 'Milo ya wiki hii'), kila mstari ambao bado haujawekwa alama una 🛒. Mguso mmoja unauongeza kwenye orodha ya ununuzi – mara moja tu, kamwe mara mbili. Uwekee ✓ hapa nao unaondoka kwenye orodha; ufute kwenye orodha na hapa hauonekani tena kama 'kwenye orodha'; uweke alama kuwa umenunuliwa kwenye orodha na mstari wa hapa unapata ✓ wenyewe. Safu yoyote ya ✓ inaweza kuunganishwa au kutenganishwa katika mipangilio ya safu.",
