    bag_ex_trips: "Safari",
    bag_ex_txt_moments: "Mambo madogo yaliyotufurahisha wiki hii:\n• Matembezi ya jioni pamoja baada ya chakula cha jioni\n• Mchoro tuliopewa zawadi\n• Vicheko vingi wakati wa chakula cha jioni",
    bag_ex_txt_recipes: "Vikombe 2 vya unga\nMayai 2\nKikombe 1 na nusu cha maziwa\nKijiko 1 kikubwa cha sukari\n\nChanganya vyote, pasha kikaango na pika pancake ndogo hadi ziwe za dhahabu.",
