    glib_weight_note: "Chagua uzito lengwa unaohisi sahihi – njia hujaa kila unapopima uzito.",
    premium_benefit_goal_library: "Maktaba yote ya malengo – mipango yote iliyo tayari",
    vision_goal_delete_routine_note: "Vipengele vyake kwenye Ratiba Yangu pia vitafutwa.",
    faq_a_goal_small_steps: "Kila lengo katika Malengo Yangu ni njia: vituo vilivyokwisha pita, jiwe la leo linalong'aa na kombe mwishoni. Lipe lengo hatua ndogo – kila siku, au kila wiki siku unayochagua – kitu kinachowezekana hata siku ngumu, kama 'Kukimbia polepole dakika 10'. Hatua ndogo zote za leo zinaonekana juu kabisa ya Malengo Yangu na kwenye Siku Yangu, kila moja na ✓ ya haraka, na '✓ Leo nimefanya' chini ya njia ya lengo hujaza nukta za siku 7 zilizopita. Kidokezo 'Njiani kuelekea 10 · hatusimami' hubaki juu kwa makusudi: hatuhitaji kuwa wakamilifu – inatosha kufanya kidogo kila siku ili kusonga mbele.",
    faq_q_goal_small_steps: "Hatua ndogo ni nini, na 'Si 10' inamaanisha nini?",
    apptour_demo_goal_small_step: "Kukimbia polepole dakika 10",
    apptour_g_today_text: "Hatua ndogo za leo za malengo yako yote, kila moja na ✓ ya haraka. Zinaonekana pia kwenye Siku Yangu.",
    apptour_g_path_text: "Vituo vilivyokwisha pita, jiwe la leo linalong'aa na kombe mwishoni. ✓ moja ndogo kwa siku inakusogeza mbele – hakuna haja ya 10.",
