    reminder_chime_big_bell: "Kengele kubwa",
    reminder_chime_melody: "Wimbo",
    reminder_chime_phone_ring: "Mlio wa simu",
    reminder_chime_alarm_clock: "Saa ya kengele",
    reminder_closed_app_hint: "📱 Programu ikiwa imefungwa, sauti ya arifa ya simu yenyewe ndiyo hulia – unaweza kuiongeza katika mipangilio ya arifa ya simu kwa programu au kivinjari (sauti na 'kuonekana kwenye skrini').",
    reminder_vibrate_label: "Tetema pamoja na sauti",
    reminder_ring_until: "Hadi kujibu",
    reminder_ring_three: "Mara 3",
    reminder_ring_once: "Mara moja",
    reminder_ring_label: "Mlio",
    calendar_event_duration_1m: "Kwa mwezi 1",
    books_lookup_none: "Hakuna kilichopatikana kwa jina hili – jaribu kuandika jina la mwandishi hapa chini.",
    books_lookup_try_author: "Hakipo hapa? Unaweza pia kuandika jina la mwandishi hapa chini.",
    nm_ch_morning_stretch_help: "Dakika 5 rahisi:\n• Mikono juu na kujinyoosha kwa muda mrefu – sekunde 30\n• Kuzungusha shingo na mabega – dakika moja\n• Kuinama mbele taratibu, magoti yakiwa laini – dakika moja\n• Kujinyoosha pembeni, kila upande – dakika moja\n• Paka-ng'ombe kwa mikono na magoti – dakika moja\nTaratibu na bila maumivu – ukipumua polepole.",
    nm_ch_slow_meal_help: "Vipi:\n• Mlo mmoja kwa siku unaochukua angalau dakika 20\n• Kuweka uma chini kati ya matonge na kutafuna vizuri\n• Glasi ya maji mwanzoni\nMwili huhitaji karibu dakika 20 kuhisi kushiba – kula taratibu huupa nafasi ya kufuata.",
    nm_ch_kitchen_closed_help: "Baada ya saa 2 usiku (20:00):\n• Maji, maji ya soda na chai ya mitishamba\n• Hakuna chakula, hakuna vitafunio na hakuna “kuonja tu”\nKidokezo: kupiga mswaki baada ya chakula cha jioni ni ishara nzuri ya “jiko limefungwa”. Chakula cha jioni cha kuchelewa ni sawa – mradi kiishe kabla ya 20:00.",
    nm_ch_no_soda_help: "Kinachohesabika kama kinywaji chenye sukari:\n• Soda na kola, chai ya baridi, vinywaji vya kuongeza nguvu\n• Juisi na nekta – hata za matunda 100%\n• Maji ya ladha yenye sukari na sharubati\nSawa: maji, maji ya soda yasiyo na sukari, maji yenye limau au mnanaa, chai na kahawa bila sukari.",
    nm_ch_fruit_dessert_help: "Mawazo:\n• Tufaha lililokatwa na mdalasini, au tufaha la kuoka\n• Zabibu zilizogandishwa au vipande vya ndizi vilivyogandishwa\n• Stroberi, tikiti, tikiti maji, embe, beri\n• Tende au matunda yaliyokaushwa – kiasi kidogo\nHamu ya kitu kitamu ni sawa kabisa – inapata tunda badala ya keki au peremende.",
    nm_ch_screen_free_meal_help: "Vipi:\n• Mlo mmoja kwa siku bila simu, TV, kompyuta au tableti\n• Kukaa mezani, kula taratibu, kuhisi ladha na kushiba\nKidokezo: simu iwe chumba kingine, au imepinduliwa ndani ya droo, muda wote wa mlo.",
    nm_ch_walk_after_meal_help: "Vipi:\n• Dakika 10 za kutembea taratibu baada ya mlo mmoja kwa siku – bora baada ya chakula cha mchana au jioni\n• Nje, kwenye korido au kuzunguka nyumba – yote yanahesabika\n• Kuongea kwa simu huku ukitembea pia kunahesabika\nMatembezi mafupi baada ya kula husaidia mmeng'enyo na kuweka nguvu sawa.",
    nm_ch_veg_each_meal_help: "Mawazo:\n• Kifungua kinywa: tango, nyanya au pilipili hoho kando ya mayai au jibini\n• Mchana: saladi au mboga zilizopikwa kando\n• Jioni: saladi ya kukatakata ya haraka, mboga za oveni au supu ya mboga\nMbichi, zilizopikwa, zilizogandishwa au kwenye saladi – zote zinahesabika.",
    nm_ch_water_first_help: "Vipi:\n• Glasi kubwa ya maji (karibu ml 300–500) mara tu baada ya kuamka\n• Kabla ya kahawa au kifungua kinywa\nKidokezo: glasi kando ya kitanda, au chupa juu ya kaunta tangu jioni – na inatokea yenyewe.",
    nm_ch_cinnamon_coffee_help: "Vipi:\n• Nusu kijiko cha chai cha mdalasini kwenye kahawa, au kwenye maziwa kabla ya kutoa povu\n• Bila sukari na bila sharubati tamu\n• Na maziwa? Ya kawaida au ya mimea yasiyoongezwa sukari\nKahawa yoyote inafaa – espresso, nyeusi, ya kuchuja au latte.",
    nm_ch_lose5_month_help: "Kila siku, mambo matatu:\n• Ndani ya bajeti ya kalori (upungufu)\n• Mazoezi ya dakika 20 au zaidi\n• Bila sukari iliyoongezwa\nChangamoto huhesabu siku, si kilo – uzito hushuka kwa kasi yake. Kupima mara moja kwa wiki, saa ileile, hutoa picha iliyo wazi zaidi.",
    nm_ch_menu_21_help: "Jinsi siku inavyowekewa alama:\n• ✓ kwenye angalau milo 3 ya menyu – au yote kama menyu ina michache\n• Mlo huru uliopangwa unahesabika kama mlo\n• Mlo uliobadilishwa (🔄) pia unahesabika – bado ni wa menyu\nSiku huwekewa alama yenyewe ✓ zikitosha.",
    nm_ch_no_snacking_14_help: "Kilicho sawa:\n• Milo na vitafunio vya menyu, kwa wakati wake\n• Vinywaji: maji, soda isiyo na sukari, chai, kahawa\nKinachohesabika kama ziada: kuonja wakati wa kupika, kumalizia sahani za watoto, kiganja cha karanga au biskuti kati ya milo.\nKidokezo: njaa kati ya milo? Maji kwanza na kusubiri dakika 10 – mlo unaofuata uko karibu.",
    nm_ch_home_food_14_help: "Kinachohesabika:\n• Kila kinachopikwa nyumbani – hata sandwichi, mayai au saladi\n• Chakula cha nyumbani kinachopelekwa kazini au shuleni\nKisichohesabika: chakula cha kuletewa, cha kubeba, mikahawa, vyakula vya haraka na milo tayari inayonunuliwa nje.\nMlo huru uliopangwa unaruhusiwa.",
    nm_ch_no_fried_14_help: "Kinachohesabika kama cha kukaanga:\n• Chipsi za viazi na krisps, schnitzel, falafel, samaki wa kukaanga\n• Maandazi, chapati za viazi na vitafunio vya kukaanga\n• Kila kinachopikwa kwenye mafuta mengi\nBadala yake: oveni, jiko la kuchoma, kikaango cha hewa au kikaangio chenye kijiko kimoja cha mafuta.\nKidokezo: schnitzel ya oveni ya kujitengenezea ni mbadala mzuri sana.",
    nm_ch_sport_14_help: "Kinachohesabika (dakika 20 au zaidi):\n• Kutembea haraka, kukimbia, baiskeli, kuogelea\n• Gym, pilates, yoga, kucheza densi, mazoezi nyumbani\n• Ngazi au michezo ya kuchangamka na watoto – dakika 20 mfululizo\nMazoezi ya dakika 20+ yaliyorekodiwa kwenye Ufuatiliaji wa Mazoezi huweka alama siku hiyo yenyewe; vinginevyo alama huwekwa hapa.",
    nm_ch_deficit_14_help: "Jinsi inavyofanya kazi:\n• Bajeti ya siku = mpango (1,300 au 1,500) + kalori za mazoezi yaliyorekodiwa siku hiyo\n• Kila kinacholiwa kinahesabika: menyu, vinywaji na kilichoongezwa kwenye Kifuatiliaji cha Chakula cha Kila Siku\n• Siku inahesabika pete ikibaki ndani ya bajeti\nKidokezo: mlo huru uliopangwa ni sawa – sehemu iliyobaki ya siku iwe nyepesi tu.",
    nm_ch_no_carbs_7_help: "Kinachohesabika kama wanga:\n• Mkate, pita, mikate midogo, krakers na keki za mchele\n• Pasta, wali, couscous, bulgur, kinoa na tambi\n• Viazi, viazi vitamu na mahindi\n• Nafaka za kifungua kinywa, shayiri na granola\n• Vitu vya kuokwa, keki, biskuti, sukari na peremende\n• Jamii ya kunde kwa wingi (dengu, choroko, maharagwe) na juisi ya matunda\nBadala ya wanga – ongeza mboga na protini zaidi: mayai, kuku, samaki, jodari, jibini laini, tofu.\nOrodha ni mwongozo – nini hasa cha kuacha ni uamuzi binafsi.",
    nm_ch_no_sugar_5_help: "Vya kuepuka:\n• Sukari nyeupe na kahawia, asali, sharubati na sharubati ya tende\n• Peremende, chokoleti, keki, biskuti na aiskrimu\n• Vinywaji vyenye sukari na juisi\n• Mtindi wenye sukari na nafaka za kifungua kinywa\nSawa: matunda, bidhaa za maziwa zisizoongezwa sukari, kahawa na chai bila sukari.\nKidokezo: ni vizuri kusoma lebo – sukari hujificha pia kwenye michuzi na kechapu.",
    nm_ch_help_btn: "Ni nini hasa kinahesabika?",
    faq_a_new_me_plans: "New Me ina mipango miwili: $11.99 kwa mwezi, au $99.99 mara moja kwa matumizi ya maisha yote. Mpango wa kila mwezi unaweza kughairiwa wakati wowote kutoka ⚙️ Mipangilio > 💳 Simamia usajili – New Me inabaki wazi hadi mwisho wa mwezi uliolipiwa. Hapo pia unaweza kuhamia maisha yote; mpango wa kila mwezi husimama wenyewe, bila malipo mara mbili. Ununuzi wa New Me kabla ya mpango wa kila mwezi kuwepo unabaki wa maisha yote. Mipango yote miwili inajumuisha Premium yote.",
    faq_q_new_me_plans: "Kila mwezi au maisha yote – New Me husimamiwa au kughairiwa vipi?",
