    faq_a_new_me_tour: "Mara tu baada ya kununua na kujaza dodoso fupi, ziara fupi inaonyesha mchezo: upau wa juu, jukumu linalofuata, changamoto ya wiki, mkoba wa maajabu na mlango 1 wa chumba cha siri. Inaweza kutazamwa tena wakati wowote kutoka ⚙️ Mipangilio > 🧭 Ziara ya New Me – jina kamili kutoka kwenye dodoso pia linaweza kubadilishwa hapo. Kabla ya kununua, New Me inaonyesha 🔒 kwenye menyu, na kuigusa kunafungua ukurasa wenye kila kilichojumuishwa.",
