    faq_a_new_me_advanced: "Hali ya juu hufunguka pamoja na zawadi, baada ya changamoto zote 20, na inaweza kuwashwa au kuzimwa kwenye 🎁 Zawadi yako. Inaipa New Me mwonekano wa dhahabu, kupanga menyu kwa uhuru – kila badiliko linaonyesha chaguo zote bila kikomo cha kalori – na skrini ya 📊 Takwimu za kina: kalori za siku 30 zilizopita ukilinganisha na mpango, siku nzuri kwa siku za wiki, mwenendo wa uzito pamoja na makadirio ya lini lengo litafikiwa, wastani wa tathmini ya jioni na historia ya changamoto.",
