    nm_gift_locked_view: "Zawadi hufunguka baada ya changamoto zote {n} – zimebaki {left}.",
    nm_gift_intro: "Changamoto zote {n}, hatua kwa hatua. Hiki ndicho kilichokuwa kinasubiri:",
    nm_gift_title: "Zawadi yako",
    faq_a_new_me_letter_gift: "Mwanzoni mwa New Me (au baadaye, kwenye Changamoto) unaweza kuandika barua kwako mwenyewe wa siku zijazo. Ikishafungwa haiwezi kusomwa wala kuhaririwa hadi ifunguke: kwenye chupa kutoka baharini katika chumba cha siri, au mwishoni mwa changamoto zote 20 – na hapo pia zawadi inasubiri.",
    faq_q_new_me_letter_gift: "Barua kutoka zamani ni nini?",
    faq_a_new_me_challenges: "🏆 Changamoto ina changamoto 20: kubwa 10 (kama siku 5 bila sukari, wiki bila wanga, au kupunguza kg 4 kwa mwezi – kila siku upungufu wa kalori, mazoezi na bila sukari) na ndogo 10 – tabia ndogo za wiki moja, kama kahawa ya mdalasini bila sukari. Unapochagua changamoto, unaulizwa lini kuanza: leo, kesho, wiki ijayo au tarehe nyingine. Changamoto moja kubwa na moja ndogo zinaweza kwenda pamoja. Changamoto inayoendelea huonekana juu kabisa ya menyu na kwenye Siku Yangu, pamoja na ✓ ya siku. Kila wiki ya changamoto huleta siku moja ya mapumziko (🍕) isiyoivunja, na siku isiyowekwa alama huhesabiwa kama siku ya mapumziko – leo na jana zinaweza kuwekwa alama. Siku nyingine huwekwa alama zenyewe: mazoezi ya dakika 20 kwenye Ufuatiliaji wa Mazoezi, au milo ya menyu yenye ✓. Kila changamoto ina ⓘ inayoeleza ni nini hasa kinahesabika (kwa mfano orodha kamili ya wanga) – ndani ya changamoto yenyewe na kando yake kwenye Siku Yangu. Chini ya hizo, 🌱 Ukuaji binafsi ina changamoto ndogo 48 za wiki moja (hazihesabiwi katika zile 20) – tazama “Changamoto ya wiki ni nini?”.",
    faq_q_new_me_challenges: "Changamoto za New Me zinafanyaje kazi?",
    nm_letter_too_short: "Maneno machache zaidi 🙂",
    nm_letter_quiz_note: "Si lazima – inaweza kuandikwa baadaye pia, kwenye Changamoto.",
    nm_letter_write: "✍️ Andika barua",
    nm_letter_sealed_line: "Imefungwa {date} · itafunguka baada ya changamoto {n}",
