    nm_letter_seal_note: "Ikishafungwa kwa muhuri, barua haiwezi kusomwa wala kuhaririwa hadi changamoto zote zikamilike.",
    nm_letter_seal: "✉️ Funga barua kwa muhuri",
    nm_letter_ph: "Niko wapi leo, ninataka kufika wapi, nini kinaniwia kigumu kuhusu chakula, ningependa kujiambia nini kwenye mstari wa mwisho…",
    nm_letter_intro: "Huandikwa sasa na kufungwa kwa muhuri – hufunguka tu baada ya changamoto zote {n}, ili kuona ni kiasi gani kimebadilika tangu wakati huo. Niko wapi sasa? Malengo yangu ni yapi, na nini kinaniwia kigumu kuhusu chakula?",
