    nm_tile_challenges: "Changamoto",
    faq_a_workout_calories: "Ndiyo. Kila zoezi hupata makadirio ya kalori zilizochomwa – kwa aina, muda na uzito wako wa karibuni (kwa kukimbia na baiskeli pia kwa kasi, umbali ukiwekwa). Yanaonekana kwenye orodha ya mazoezi na muhtasari wa mwezi (Zilizochomwa), na huongezwa kwenye bajeti ya kalori ya siku hiyo: kwenye Kifuatiliaji cha Chakula cha Kila Siku, kwenye Vipimo vya Kalori na Uzito na kwenye pete ya New Me. Ni makadirio, ndiyo maana yanaonyeshwa na ~.",
    faq_q_workout_calories: "Je, mazoezi yanahesabiwa kwenye kalori za siku?",
    faq_a_new_me_flexible_menu: "Ndiyo. Kwenye dodoso na kwenye mipangilio unachagua milo mingapi kwa siku – Milo 2 + kitafunio / Milo 2 + chakula chepesi cha jioni / Milo 2 + kitafunio + chakula chepesi cha jioni – na ➖ kwenye kadi ya mlo huuondoa (angalau 3 hubaki); '➕ Rudisha' huurudisha. Kwa vyovyote vile kalori za siku hubaki zile zile: kilichoondolewa hugawanywa kwa milo mingine, na chini ya kila mlo imeandikwa kiasi kilichoongezwa na kinachoweza kuliwa pamoja. ✏️ Hariri kwenye mlo hufungua maandishi yake – badilisha unachotaka (mfano bila mkate au yai moja zaidi) na AI hukokotoa upya kalori na protini. 🔄 Badilisha hutoa machaguo ya menyu, ⭐ Vilivyohifadhiwa na ✨ Andika; kila badiliko linaweza kuwa la leo tu au kuanzia sasa. Na mwishoni mwa 'Siku nzima' kuna ➕ Ongeza chakula – andika kilicholiwa nje ya menyu, na AI hukokotoa na kuongeza kwa leo (✕ hufuta).",
    faq_q_new_me_flexible_menu: "Je, naweza kubadilisha idadi ya milo katika New Me, au kula mlo wangu mwenyewe?",
