    faq_a_app_tour: "Ziara hufunguka yenyewe mara moja, unapoingia kwa mara ya kwanza. Huanza na sehemu zake – gusa moja ili uende moja kwa moja huko – kisha huonyesha kila sehemu ya programu (skrini ya mwanzo, msaidizi wa AI na kila kipengee kwenye menyu) na makundi matano ya Mipangilio, kila moja na maelezo mafupi, na huchungulia ndani ya baadhi yake (kwa mfano njia ya lengo ya mfano, begi na Google Calendar). Endelea husonga mbele, Rudi hurudi nyuma, Ruka sehemu hii huenda kwenye sehemu inayofuata na ✕ hufunga ziara. Unaweza kuitazama tena wakati wowote kutoka Mipangilio > Msaada na Matumizi > Ziara ya Programu, na kuendelea ulipoishia. Endelea na Rudi daima hukaa mahali pamoja chini ya skrini, na kwenye kompyuta vitufe vya mishale vya kibodi pia hufanya kazi.",
    faq_q_app_tour: "Ninaonaje tena ziara ya programu?",
    apptour_done_text: "Una swali? Msaada na Maswali Yanayoulizwa Mara kwa Mara katika Mipangilio hujibu kila kitu, na ziara hii iko daima chini ya Msaada na Matumizi.",
    apptour_done_title: "Ni hayo tu! 🎉",
    apptour_flow_recurring: "Malipo ya awamu na maagizo ya kudumu",
    apptour_flow_weight: "Uzito",
