    apptour_connect_text: "Unachofanya mahali pamoja husasisha pengine kiotomatiki:",
    apptour_connect_title: "Kila kitu kimeunganishwa",
    apptour_s_support_text: "Msaada na Maswali Yanayoulizwa Mara kwa Mara, wasiliana nasi, kushiriki programu – na ziara hii, wakati wowote.",
    apptour_s_account_text: "Premium, nenosiri, ripoti binafsi ya PDF, usawazishaji wa Google Calendar na kufuta akaunti.",
    apptour_s_notifications_text: "Arifa za ukumbusho na sauti yake. '⏰ Bado' kwenye kikumbusho hufanya kazi kama kuahirisha kengele: hukumbusha tena kila baada ya dakika 5.",
    apptour_s_personalization_text: "Nchi, milo na vitafunio kwa siku, mwezi wako wa kifedha unapoanza, na kinachoonyeshwa kwenye skrini ya kwanza.",
    apptour_s_appearance_text: "Lugha, hali ya mwanga au giza, mandhari, fonti, rangi ya maandishi, ufikivu na ukubwa wa onyesho.",
    apptour_m_style_text: "Kitufe hiki hubadilisha menyu kuwa vigae vikubwa – na kurudi. Skrini ya kwanza huonyesha kimoja tu kati ya hivyo.",
    apptour_m_style_title: "Orodha au vigae",
    apptour_m_receipts_link: "Hamisha kategoria kama PDF, au jumlisha kila kitu kwa miaka kwa 🧮.",
    apptour_m_receipts_text: "Hifadhi ankara za kodi na risiti pamoja na picha, kwa nyumbani au biashara.",
    apptour_m_budget_link: "Malipo ya awamu na maagizo ya kudumu (pamoja na kuingiza kutoka Excel), kategoria zako mwenyewe na siku ya kuanza upya bajeti katika Mipangilio.",
    apptour_m_budget_text: "Matumizi na mapato kwa kategoria, pamoja na salio la mwezi.",
