    apptour_m_sport_text: "Mpango wa mazoezi wa wiki, na kurekodi mazoezi kwa aina, muda na umbali – hata pamoja na picha.",
    apptour_m_water_text: "Fuatilia kiasi cha maji unachokunywa dhidi ya lengo la kila siku.",
    apptour_m_calories_link: "Ufuatiliaji wa uzito pia uko hapa – unashirikiwa na New Me na malengo ya uzito katika Malengo Yangu.",
