    apptour_m_shopping_text: "Orodha yako ya ununuzi – weka alama kwenye vitu ukiwa dukani.",
    apptour_m_notes_link: "Buruta ujumbe hadi 'Leo', 'Kesho' au tarehe nyingine kuugeuza kuwa kazi; jumbe zilizofutwa husubiri katika 🗑️ kumbukumbu.",
    apptour_m_notes_text: "Maelezo na mawazo katika orodha moja.",
