    table_select_option_delete_confirm: "Chaguo hili linatumika katika mistari {count}. Lifutwe? Visanduku hivyo vitaachwa tupu.",
    table_select_option_delete_title: "Futa chaguo",
    faq_a_other_manual_option: "Kila mahali unapochagua kutoka kwenye orodha ya chaguo, pia kuna '✏️ Nyingine' - lichague kisha uandike hasa unachohitaji. Kwenye jedwali lenye safu ya uchaguzi (kwa mfano 'Uhusiano' katika jedwali la zawadi), gusa kisanduku, chagua '✏️ Nyingine', andika thamani (kwa mfano 'Mpwa') kisha ugonge Ongeza - huhifadhiwa kama chaguo jipya la safu hiyo, hivyo wakati ujao tayari litakuwa kwenye orodha. Alama ndogo ya × kando ya kila chaguo katika orodha hiyo hufuta chaguo hilo kutoka kwenye safu. Unapochagua aikoni ya jedwali kuna aikoni nyingi (zikiwemo noti za kunata za rangi). Inafanya kazi vivyo hivyo kwa kategoria za vyakula vilivyohifadhiwa, kategoria za mapishi, kategoria za matumizi yanayojirudia (huhifadhiwa kama kategoria mpya binafsi) na kategoria za malengo katika Malengo Yangu.",
