    receipts_total_title: "Jumla ya risiti zote",
    receipts_total_tile: "Jumla ya risiti zote",
    faq_a_quick_note_apple: "🍎 iliyo kando ya 📝 na 🛒 kwenye dirisha la kumbukumbu ni njia ya mkato ya kurekodi haraka mojawapo ya milo yako iliyohifadhiwa kwenye Kifuatiliaji cha Chakula cha Kila Siku cha leo. Imewashwa kwa chaguo-msingi - ikiwa huihitaji, izime katika Mipangilio > Ubinafsishaji na Kalenda ('Onyesha njia ya mkato ya 🍎 ya milo iliyohifadhiwa kwenye dirisha la kumbukumbu'), na uiwashe tena hapo wakati wowote.",
    faq_q_quick_note_apple: "🍎 kwenye dirisha la kumbukumbu ni nini, na inaweza kufichwa?",
    settings_quick_note_apple_label: "Onyesha njia ya mkato ya 🍎 ya milo iliyohifadhiwa kwenye dirisha la kumbukumbu",
    faq_a_vision_board_today: "Katika Malengo Yangu, chini ya njia ya lengo (kwenye 'Mpango'), gusa 📅 karibu na kituo na uchague tarehe. Unaweza pia kuwasha '🔁 Kila wiki hadi ikamilike' – kisha kituo kitarudi kila wiki siku ileile hadi ukiwekee alama mara moja. Kituo kinaonekana siku hiyo kwenye Siku Yangu na kwenye kalenda (na kwenye Google Calendar, ikiwa imeunganishwa), na kitufe kinaonyesha kimepangwa lini. ✓ mahali pamoja huweka alama mahali pengine pia na kusogeza mbele njia ya lengo. Gusa 📅 tena ili kubadilisha tarehe au kukiondoa kwenye kalenda. Kufuta kazi ya mara moja kwenye kalenda pia hufuta kituo hicho kwenye lengo; kufuta wiki moja ya ukumbusho wa kila wiki huondoa wiki hiyo tu.",
    faq_q_vision_board_today: "Nawezaje kuweka kituo cha lengo kwenye kalenda (📅)?",
    vision_milestone_already_today: "Hatua hii tayari iko kwenye kazi za leo.",
