    nm_extras_title: "Pia kimeliwa leo",
    nm_drinks_total: "{n} / ~{kcal} kcal",
    nm_drink_missing: "Weka jina la kinywaji na kalori zake",
    nm_drink_more: "+ Kinywaji kingine",
    nm_drink_add: "Ongeza",
    nm_drink_name_ph: "Kinywaji (k.m. juisi)",
    nm_drinks_hint: "Andika tu jina la kinywaji – kalori huhesabiwa kiotomatiki, na namba inaweza kubadilishwa.",
    nm_slot_drinks: "Vinywaji",
    faq_a_new_me_tracking: "Gusa jukumu linalofuata juu ya New Me kisha ✓ Nimekula ili kuweka alama kwamba mlo unaofuata umeliwa – menyu nzima yenye ✓ kwa kila mlo iko kwenye Siku nzima, upande wa pembeni, na milo ya leo pia huonekana kwenye Siku Yangu kwenye skrini ya mwanzo – kugusa mmojawapo hapo (au kupitisha kipanya juu yake) huonyesha hasa nini cha kula, pamoja na ✓ na Badilisha. Kila kitu kinasawazishwa na Kifuatiliaji cha Chakula cha Kila Siku: milo ya mpango, vinywaji na chochote unachoongeza mahali pengine (mfano kahawa kutoka kuongeza haraka) huhesabiwa pamoja kwenye New Me na kwenye Siku Yangu – hakuna ulichokwisha kuandika kinachofutwa, na kuondoa ✓ huondoa sehemu ya New Me pekee. Milo yote ya leo ikiwekwa alama kunakuwa na sherehe ndogo. Kwenye “Vinywaji”, andika vinywaji vya siku – vyote kwa pamoja hadi kalori ~150, yaani takriban vinywaji 3 vya hadi kalori ~50 kila kimoja. Andika tu jina la kinywaji na kalori hujazwa kiotomatiki na AI. Mistari miwili ya kahawa/chai pia ina sehemu ya “Maziwa? Kiasi gani?” (mfano “kidogo” au “ml 50”), na hesabu husasishwa; namba inaweza kubadilishwa kabla ya kuongeza na pia baadaye. Kinywaji chenye jina na kalori huhifadhiwa kiotomatiki mara tu unapoendelea – kugusa Ongeza ni hiari. Gusa ☆ kando ya kinywaji ili kukihifadhi kama kinywaji cha kawaida – vinywaji vya kawaida huonekana kama vitufe juu ya kadi ya Vinywaji, na mguso mmoja huviongeza kwenye siku. ⭐ huhifadhi mlo kama mlo uliohifadhiwa. “Jedwali la siku” huonyesha ulichokula pamoja na kalori na protini. 💎 ndogo kando ya hali ya umakini juu ya skrini ya mwanzo hukifungua moja kwa moja. Thamani za kalori na protini ni makadirio ya AI na zinaweza kuwa na makosa. Hukula chote? Chini ya mlo uliowekwa alama, “Sikula chote?” huondoa robo, nusu au robo tatu ya sehemu – au unachoandika, kwa hesabu – na kalori za siku husasishwa.",
    faq_q_new_me_tracking: "✓, ubadilishaji na kalori hufanyaje kazi katika New Me?",
    faq_a_new_me_what: "New Me ni programu tofauti ya menyu ya kila siku yenye mipango miwili iliyo tayari – kalori 1,300 au 1,500 – inayoundwa na milo mikuu 2 na vitafunio 2, kila kimoja kikiwa na chaguo 3. Inajumuisha Premium yote. Bei: $11.99 kwa mwezi (ghairi wakati wowote) au $99.99 mara moja, maisha yote. Ifungue kutoka 💎 New Me kwenye menyu. Kabla ya kuanza kuna dodoso fupi linaloanza na tamko la kitabibu linalopaswa kukubaliwa. Programu ni taarifa za jumla tu na haichukui nafasi ya daktari au mtaalamu wa lishe wa kitabibu.",
