    nm_disclaimer_terms_link: "Masharti Kamili ya Matumizi",
    nm_disclaimer_agree: "Nimesoma yaliyo hapo juu, nina umri wa miaka 18 au zaidi, na ninakubali",
    nm_disclaimer_p4: "4. Ukomo wa dhima. Matumizi ya programu ni kwa hatari ya mtumiaji mwenyewe. Watengenezaji na waendeshaji wa programu hii hawatawajibika kwa madhara yoyote ya moja kwa moja au yasiyo ya moja kwa moja, ya kiafya au mengineyo, yatokanayo na matumizi ya programu, menyu zake, au thamani za kalori na protini zinazoonyeshwa, ambazo ni makadirio ya takriban tu.",
    nm_disclaimer_p3: "3. Haikusudiwi, bila idhini ya kitabibu, kwa: wanawake wajawazito au wanaonyonyesha, watoto walio chini ya umri wa miaka 18, mtu yeyote aliye na au aliyewahi kuwa na tatizo la ulaji, mtu yeyote aliye na ugonjwa sugu au ugonjwa wa msingi (ikiwa ni pamoja na kisukari, ugonjwa wa moyo, figo au ini), au mtu yeyote anayetumia dawa mara kwa mara, isipokuwa idhini ya wazi imepatikana kutoka kwa daktari anayemtibu.",
    nm_disclaimer_p2: "2. Uchaguzi wa mpango. Uchaguzi wa mpango wa kalori 1,300 au wa kalori 1,500 unafanywa kwa hiari na jukumu la mtumiaji pekee. Inapendekezwa kushauriana na daktari au mtaalamu wa lishe wa kitabibu kabla ya kuanza lishe yoyote ya kupunguza kalori.",
    nm_disclaimer_p1: "1. Taarifa za jumla pekee. Programu ya New Me na menyu zake hutoa taarifa za jumla za lishe na hazijumuishi ushauri wa kitabibu, wa lishe wala ushauri mwingine wowote wa kitaalamu. Haziwezi kuchukua nafasi ya ushauri, uchunguzi au matibabu kutoka kwa daktari au mtaalamu wa lishe wa kitabibu aliyepewa leseni. Ni lazima kushauriana na daktari kabla ya kufanya mabadiliko yoyote ya lishe au kuanza mazoezi ya mwili.",
    nm_disclaimer_title: "Kanusho la kitabibu",
    nm_step_of: "Hatua {n} kati ya {total}",
    nm_unlock_pending: "Malipo yamepokelewa – inaweza kuchukua dakika moja kuonekana. Tafadhali onyesha upya baada ya muda mfupi.",
    nm_unlocked_toast: "New Me imefunguliwa – karibu! 💎",
    nm_unlocking: "Inathibitisha ununuzi wako…",
    nm_buy_btn: "Pata New Me",
    nm_sales_f4: "Menyu kamili kama PDF kwa lugha yako",
    nm_sales_f3: "Mwonekano wa kila mwezi pamoja na ufuatiliaji wa uzito",
    nm_sales_f2: "✓ ya kila siku kwa kila mlo, pamoja na kalori zilizobaki leo",
    nm_sales_f1: "Mipango miwili tayari (1,300 / 1,500 kcal) yenye chaguo 3 kwa kila mlo",
    nm_sales_subtitle: "Menyu ya kila siku iliyo tayari ya kalori 1,300 au 1,500 – pamoja na ufuatiliaji, ubadilishaji mahiri, changamoto na safari ya maendeleo.",
    faq_a_categories_menu: "Menyu ya programu inaweza kuonyeshwa kwa mojawapo ya njia mbili, na kitufe kimoja tu huonekana juu: ☰ orodha (chaguo-msingi), au ▦ vigae vikubwa - Mipango na Kalenda, Orodha, Malengo na Maendeleo, Lishe na Vipimo, Michezo, na Matumizi na Mapato; gusa kigae ili kuona kilichomo, kisha gusa unachohitaji. Ili kubadili, fungua menyu kisha gusa kitufe kidogo kilicho juu yake: ▦ kwenye menyu ya orodha hubadilisha kuwa vigae, na ☰ kwenye menyu ya vigae hurudisha kwenye orodha. Menyu ya vigae pia ina kitufe cha ⚙️ cha Mipangilio. Chaguo lako huhifadhiwa na hutumika kwenye vifaa vyako vyote.",
    faq_q_categories_menu: "Ninabadilishaje kati ya menyu ya orodha ☰ na menyu ya vigae ▦?",
    new_me_coming_soon: "Programu mpya ya binafsi iko njiani - inakuja hivi karibuni.",
    categories_menu_title: "Kategoria Zote",
    hamburger_group_planning: "Mipango na Kalenda",
    routine_overview_no_checks: "Bado hakuna alama mwezi huu - gusa ✓ kando ya vipengele vya ratiba yako siku unazovifanya.",
    faq_a_finance_cycle_day: "Kwa chaguo-msingi muhtasari wa bajeti yako unawekwa upya tarehe 1 ya kila mwezi wa kalenda. Ikiwa unalipwa siku tofauti (tuseme tarehe 10), weka siku hiyo hapa badala yake - muhtasari wako wa mwezi, historia, na bajeti lengwa vitaanzia siku hiyo hadi siku hiyo hiyo ya mwezi unaofuata, badala ya tarehe 1 hadi mwisho wa mwezi.",
    faq_q_finance_cycle_day: "Mpangilio wa 'Siku ya kuweka upya bajeti ya mwezi' hufanya nini?",
    faq_a_quick_note_view_full_lists: "Kwenye menyu ☰, Maelezo na Orodha ya Ununuzi viko pale pale. Kwenye dirisha la Maelezo ya Haraka (katika Hali ya umakini), 📝 na 🛒 vidogo kando ya Ongeza pia vinakupeleka huko, na 🍎 huandika haraka mojawapo ya milo yako uliyohifadhi.",
    faq_q_quick_note_view_full_lists: "Ninaonaje Maelezo yangu yote au Orodha kamili ya Ununuzi kutoka kwa Maelezo ya Haraka?",
    settings_terms_link: "📄 Masharti ya Matumizi",
