    note_triage_otherdate: "Tarehe Nyingine", note_triage_otherdate_modal_title: "Chagua Tarehe", note_triage_otherdate_missing: "Tafadhali chagua tarehe", note_triage_success_otherdate: "Imeongezwa kwenye ratiba yako!", notes_ai_placeholder_shopping: "Ongeza kwenye orodha",
    daily_greeting_morning: "Habari za asubuhi!", daily_greeting_afternoon: "Habari za mchana!", daily_greeting_evening: "Habari za jioni!", daily_greeting_night: "Usiku mwema!", calorie_monthly_view_title: "Muonekano wa Kila Mwezi", calorie_monthly_avg_label: "Wastani wa kila siku:", calorie_monthly_avg_empty: "Bado hakuna data iliyorekodiwa mwezi huu", calorie_monthly_day_total_label: "Jumla ya siku:", notes_ai_added_shopping: "Imeongezwa kwenye orodha yako ya ununuzi", quick_note_dest_notes: "📝 Maelezo", quick_note_dest_shopping: "🛒 Orodha ya Ununuzi",
    faq_q_calorie_monthly_view: "Ninawezaje kuona historia yangu ya kalori kwa mwezi mzima?", faq_a_calorie_monthly_view: "Vipimo vya Kalori na Uzito vina kadi ya 'Muonekano wa Kila Mwezi' yenye kalenda - kila siku uliyorekodi chakula inapata nukta, na wastani wa kila siku wa mwezi huo unaonyeshwa juu ya gridi. Gusa siku yoyote kuona ulichokula hasa na jumla yake. Muhtasari huo huo pia unajumuishwa unapopakua Ripoti yako Binafsi (PDF) kutoka kwa Mipangilio, ikiwa sehemu ya Vipimo vya Kalori na Uzito imeteuliwa.",
    faq_q_calorie_stats_total_vs_average: "Je, namba za Kila Wiki/Kila Mwezi katika Vipimo vya Kalori na Uzito ni jumla au wastani?", faq_a_calorie_stats_total_vs_average: "Zote mbili - namba kubwa ni jumla (jumla) ya kila kitu kilichorekodiwa katika wiki/mwezi wa sasa wa kalenda, na mstari mdogo chini yake ni wastani wa kila siku. Wastani unagawanywa tu kwa siku ulizorekodi kitu kweli, sio kwa 7 au mwezi mzima - siku isiyo na rekodi yoyote inarukwa tu, haihesabiwi kama 0 wala haipunguzi wastani.",
    faq_q_weight_note: "Je, ninaweza kuongeza dokezo kwenye kipimo cha uzito?", faq_a_weight_note: "Ndiyo - kuna sehemu ya dokezo la hiari kando ya sehemu za uzito/tarehe katika Ufuatiliaji wa Uzito wa Mara kwa Mara (unapatikana chini kabisa ya Lishe na Vipimo > Vipimo vya Kalori na Uzito, chini ya ⚖️). Litumie kutoa muktadha kama \"baada ya mazoezi\" au \"kupima asubuhi\" - dokezo hilo linaonekana kando ya kipimo hicho kwenye orodha ya historia.",
    faq_q_quick_note_shopping_list: "Je, Maelezo ya Haraka yanaweza kuongeza moja kwa moja kwenye orodha yangu ya ununuzi?", faq_a_quick_note_shopping_list: "Ndiyo – kwenye mstari wa kuandika katikati ya skrini kuu, gusa 📝 ulio mwanzoni: unakuwa 🛒, na unachoandika kinaenda moja kwa moja kwenye Orodha ya Ununuzi bila kupitia Maelezo.",
