    food_estimate_confirm_summary: "Makadirio: {calories} kcal · gramu {protein} za protini", food_estimate_confirm_btn: "✓ Inaonekana sawa, endelea", food_estimate_reject_btn: "✗ Haionekani sahihi", food_estimate_reject_question: "Kuna nini kibaya? Eleza tena, au ongeza maelezo yaliyokosekana.",
