    daily_focus_p1_d3_s1: "Kubaki nikiwa na uhusiano na nanga yangu ya ndani hata mazingira yakiwa na taharuki", daily_focus_p1_d3_s2: "Kupunguza mwendo na kujipatia nafasi za umakini safi", daily_focus_p1_d3_s3: "Kuweka uwazi na uwazi wa mawasiliano na watu wanaonizunguka", daily_focus_p1_d3_s4: "Kuzingatia jambo moja tu kwa wakati mmoja", daily_focus_p1_d3_s5: "Kuthamini mafunzo na ukuaji kutoka kwa kila tajriba",
