    daily_focus_p1_d6_s1: "Kuweka thamani yangu binafsi ikiwa thabiti na imara", daily_focus_p1_d6_s2: "Kuzingatia kinachotokea sasa na kufurahia wakati huo", daily_focus_p1_d6_s3: "Kubaki na subira na kuiamini kabisa mchakato wangu", daily_focus_p1_d6_s4: "Kujua wakati wa kutenda na wakati wa kuachilia kwa upole", daily_focus_p1_d6_s5: "Kurejesha hisia yenye afya na nzuri ya uwiano katika kila jambo",
    daily_focus_p1_d7_s1: "Kutengeneza nafasi yenye heshima kwa mapumziko ya kina na yenye kutuliza", daily_focus_p1_d7_s2: "Kusikiliza utulivu wangu wa ndani na kuruhusu mwili kupumzika", daily_focus_p1_d7_s3: "Kujizunguka na maneno mazuri na mawazo yenye kupendeza", daily_focus_p1_d7_s4: "Kuachilia majukumu yote na kujitolea kwa wakati wenye thamani", daily_focus_p1_d7_s5: "Kujaza moyo wangu na shukrani kwa safari niliyopitia",
    daily_focus_p2_d1_s1: "Kuweka eneo langu la kazi kimya na bila vikwazo", daily_focus_p2_d1_s2: "Kusikiliza mahitaji ya leo na kutanguliza jambo muhimu zaidi", daily_focus_p2_d1_s3: "Kuchagua mazungumzo chanya ya ndani yanayonisukuma kuchukua hatua", daily_focus_p2_d1_s4: "Kuanza moja kwa moja na jambo kuu na kujenga kasi", daily_focus_p2_d1_s5: "Kuanza siku kwa dhamira na mtazamo wa mafanikio",
    daily_focus_p2_d2_s1: "Kuzingatia ratiba yangu na kutumia muda kwenye jambo muhimu zaidi", daily_focus_p2_d2_s2: "Kutenda kutokana na uamuzi ulio wazi na thabiti", daily_focus_p2_d2_s3: "Kuitikia mabadiliko kwa unyumbufu na kurudi haraka kwenye mstari", daily_focus_p2_d2_s4: "Kuchagua uthabiti katika majukumu yangu na kujenga nidhamu imara", daily_focus_p2_d2_s5: "Kuthamini juhudi ninazoweka katika kutimiza ahadi yangu",
    daily_focus_p2_d3_s1: "Kubaki nikiwa nimeunganika na malengo yangu na kuongeza umakini", daily_focus_p2_d3_s2: "Kupunguza kasi ili kutenda kwa usahihi na ubora wa hali ya juu", daily_focus_p2_d3_s3: "Kudumisha uwazi kamili katika kila mazungumzo na uratibu", daily_focus_p2_d3_s4: "Kuzingatia jambo moja hadi likamilike kabisa", daily_focus_p2_d3_s5: "Kupata funzo haraka kutoka kila changamoto na kuendelea mbele",
    daily_focus_p2_d4_s1: "Kudumisha mwendo sahihi wa kazi unaojenga nguvu nyingi", daily_focus_p2_d4_s2: "Kuchukua mapumziko ya makusudi ili kuongeza umakini", daily_focus_p2_d4_s3: "Kuamini mpango wangu wa kazi na kuushikilia", daily_focus_p2_d4_s4: "Kugawanya jukumu kubwa katika hatua rahisi na zenye mpangilio", daily_focus_p2_d4_s5: "Kutambua maendeleo mazuri niliyoyafanya siku za hivi karibuni",
    daily_focus_p2_d5_s1: "Kudumisha kiwango changu cha juu na ubora wa utekelezaji", daily_focus_p2_d5_s2: "Kujaza akili yangu na vitendo halisi vinavyonisogeza mbele", daily_focus_p2_d5_s3: "Kuchagua kukamilisha majukumu kwa urahisi na mtiririko", daily_focus_p2_d5_s4: "Kumaliza mambo yaliyobaki na kukamilisha kazi kwa akili safi", daily_focus_p2_d5_s5: "Kuamini nidhamu yangu binafsi, inayozidi kuimarika",
    daily_focus_p2_d6_s1: "Kudumisha uwiano sahihi kati ya kazi na mapumziko", daily_focus_p2_d6_s2: "Kufanya muhtasari wa siku za hivi karibuni kwa uwepo na mafunzo yaliyopatikana", daily_focus_p2_d6_s3: "Kubaki na subira na mchakato unaojengwa hatua kwa hatua", daily_focus_p2_d6_s4: "Kuthamini kila kitu nilichokifanikisha na kupumzika kwa utulivu", daily_focus_p2_d6_s5: "Kujaa kuridhika kutokana na nidhamu niliyoonyesha",
    daily_focus_p2_d7_s1: "Kuacha siku hii kwa ajili ya kuchaji nguvu na upya kamili", daily_focus_p2_d7_s2: "Kusikiliza hamu yangu ya ndani na kufanya mambo yanayonijaza", daily_focus_p2_d7_s3: "Kujipa sifa kamili kwa uvumilivu wangu na safari niliyopitia", daily_focus_p2_d7_s4: "Kuachilia mipango yote na kufurahia uhuru wa kiakili", daily_focus_p2_d7_s5: "Kushukuru kwa uwezo wa kuvumilia, kujifunza na kuboreka",
