    faq_q_daily_focus_prompt: "Ukumbusho mdogo unaouliza jambo muhimu zaidi la kufanya leo ni nini?", faq_a_daily_focus_prompt: "Ni ukumbusho wa kila siku wa Premium: mara moja kwa siku beji ndogo ya “1” inaonekana kwenye aikoni ya msaidizi wa AI. Gusa beji kufungua kiputo kinachouliza ni nini muhimu zaidi kwako kufanya leo, na mapendekezo 5 yaliyo tayari yanaonekana humo papo hapo (yanabadilika kila siku, yakizunguka mada tofauti mwaka mzima ili yabaki mapya) pamoja na 'Nyingine' kuandika lako mwenyewe - unaweza kuchagua zaidi ya moja. Gusa Ongeza, na machaguo yako yanaonekana kama lebo ndogo za ukumbusho juu ya 'Siku Yangu' (si kazi za kuwekewa alama). Ukiifunga kwa ✕ au ukigusa nje yake, beji inafifia tu kwa siku iliyobaki badala ya kutoweka. Imewashwa kwa chaguo-msingi, lakini unaweza kuizima katika Mipangilio > Ubinafsishaji na Kalenda. Leo haifai? Gusa '🌙 Si leo' – beji hupotea hadi kesho, kisha swali hurudi kama kawaida. Pendekezo moja linatoka kwenye maisha yako mwenyewe – hatua inayofuata ya lengo la mwezi au usomaji wa leo. Kila siku huanza upya.",
